// Bespoke 108 Curriculum comparison tables for 100% individualization (188/188 units)
add('math-4', "一元一次方程式：等量公理與移項法則", [["同加減公理","等號兩邊加減相同數，等式維持成立","x - 5 = 12 → x = 12 + 5 = 17"],["同乘除公理","等號兩邊乘除相同非零數，除數必不能為 0","3x = 18 → x = 18/3 = 6；不可同除以 0"],["移項變號","移過等號變相反運算（加變減、乘變除）","2x + 7 = 15 → 2x = 15 - 7 = 8"],["代回驗算","將求得之 x 代入原方程式左式與右式檢核","2(4) + 7 = 15 左右相等，解正確"]]);
add('math-5', "二元一次聯立方程式：代入與加減消去法", [["代入消去法","其中一式某一未知數係數為 1 或 -1 時最簡便","x = 2y + 3 代入 3x - 4y = 11 消去 x"],["加減消去法","兩式中某未知數係數相同或相反時，利用相減或相加","2x + 3y = 8 與 2x - y = 4 兩式相減直接消去 2x"],["解的幾何意義","聯立方程式的解對應兩條直線在直角坐標上的交點","恰有一組解（相交）、無解（平行）、無限多組解（重合）"],["應用題假設","明確假設兩個未知數與單位，並列出兩個獨立等式","設雞 x 隻、兔 y 隻；x + y = 35 且 2x + 4y = 94"]]);
add('math-9', "乘法公式與多項式運算規律", [["和的平方公式","(a + b)² = a² + 2ab + b²，切勿漏寫中間項 2ab","(x + 5)² = x² + 10x + 25，非 x² + 25"],["差的平方公式","(a - b)² = a² - 2ab + b²，平方項恆正，中間項帶負號","(2x - 3)² = 4x² - 12x + 9"],["平方差公式","(a + b)(a - b) = a² - b²，無中間交叉項","(3x + 4)(3x - 4) = 9x² - 16"],["多項式除法","被除式 = 除式 × 商式 + 餘式，餘式次數必小於除式次數","一次除式之餘式必為常數；缺項必須補零對齊"]]);
add('math-11', "因式分解方法：提公因式、分組與十字交乘", [["提公因式","觀察各項共有因數或多項式因式，提出後保留括號內剩餘","3x² - 6x = 3x(x - 2)"],["公式法分解","辨識平方差 a² - b² 或完全平方 a² ± 2ab + b²","4x² - 9 = (2x + 3)(2x - 3)"],["十字交乘法","二次項係數拆兩端，常數項拆兩端，交叉相乘和等於一次項係數","x² - 5x + 6 = (x - 2)(x - 3)，(-2)+(-3)=-5"],["分組分解法","四項式分兩兩一組或三一分組（製造完全平方差）","x² - y² + 2x + 1 = (x + 1)² - y² = (x + 1 + y)(x + 1 - y)"]]);
add('math-12', "一元二次方程式解法與判別式判定", [["因式分解求解","將方程式整理為 AB = 0 形式，則 A = 0 或 B = 0","(x - 3)(x + 2) = 0 → x = 3 或 -2"],["配方法步驟","二次項係數化為 1，常數項移右邊，兩邊同加 (b/2)²","x² + 6x = 7 → x² + 6x + 9 = 16 → (x + 3)² = 16"],["公式解與判別式","x = (-b ± √(b² - 4ac)) / (2a)；D = b² - 4ac","D > 0 兩相異實根；D = 0 兩相等實根（重根）；D < 0 無實數解"],["幾何情境驗根","邊長、時間、人數等實際物理量必為正數，負根或不合者應捨去","求長方形邊長 x，若得 x = 8 或 -3，捨去 -3"]]);
add('math-13', "等差數列通項與規律探索", [["公差定義","後項減前項之固定差值 d = aₙ - aₙ₋₁","數列 5, 2, -1, -4 之公差 d = 2 - 5 = -3"],["第 n 項公式","aₙ = a₁ + (n - 1)d，共有 (n - 1) 個公差間距","首項 4、公差 3，第 15 項 a₁₅ = 4 + 14 × 3 = 46"],["等差中項","若 a, b, c 成等差，則 b = (a + c) / 2","7 與 19 的等差中項為 (7 + 19)/2 = 13"],["項數求法","項數 n = (末項 - 首項)/公差 + 1，n 必為正整數","求 7, 11, ..., 99 的項數：n = (99 - 7)/4 + 1 = 24"]]);
add('math-22', "等差級數求和與梯形公式應用", [["首末項求和公式","Sₙ = n(a₁ + aₙ) / 2，項數乘以平均值","首項 3、末項 39、項數 10：S₁₀ = 10(3 + 39)/2 = 210"],["公差求和公式","Sₙ = n[2a₁ + (n - 1)d] / 2，未知末項時使用","首項 5、公差 4：S₈ = 8[2(5) + 7(4)]/2 = 8(38)/2 = 152"],["級數與通項關係","aₙ = Sₙ - Sₙ₋₁（n ≥ 2）；a₁ = S₁","已知 Sₙ = 2n² + 3n，則 a₁ = S₁ = 5，a₂ = S₂ - S₁ = 14 - 5 = 9"],["生活情境求和","堆疊木樁、劇院座位、存錢計畫等應用問題","最前排 20 坐位，每排增 2 位，共 15 排：S₁₅ = 15[40 + 14×2]/2 = 510"]]);
add('math-14', "三角形全等判定定理（SSS, SAS, ASA, AAS, RHS）", [["邊角邊 (SAS)","兩邊及其「夾角」對應相等方成立","兩邊與非夾角 (SSA) 不能判定全等（可能產生兩種三角形）"],["角邊角與角角邊","ASA（兩角及夾邊）與 AAS（兩角及對邊）皆能唯一確定形狀與大小","已知兩角即確定第三角（內角和 180°），故 AAS 可化為 ASA"],["三邊對應相等 (SSS)","三邊長度分別對應相等，形狀大小完全鎖定","三角形具有結構剛性穩定度，由 SSS 保證"],["直角三角形 RHS","直角三角形中，斜邊 (H) 與一股 (S) 對應相等","因畢氏定理可推得另一股亦相等，故為全等定理特例"]]);
add('math-16', "相似三角形判定與比例線段定理", [["AA 相似定理","兩組對應角相等即相似（第三角必相等）","最常用之相似判定，常配合平行線之內錯角或同位角相等"],["平行線截比例線段","三角形中平行於一邊的直線截另兩邊成比例線段","DE // BC 則 AD/AB = AE/AC = DE/BC"],["SAS 與 SSS 相似","兩組對應邊成比例且夾角相等 (SAS)；三組對應邊成比例 (SSS)","對應邊長比為 k，則對應周長比為 k，對應面積比為 k²"],["母子相似性質","直角三角形斜邊高將原三角形分為兩個與原圖相似的小直角三角形","AB² = BD × BC；AC² = CD × BC；AD² = BD × CD"]]);
add('math-15', "平行四邊形性質與判別條件", [["對邊與對角性質","平行四邊形兩組對邊分別等長、兩組對角分別相等、同側內角互補","若 ∠A = 70°，則對角 ∠C = 70°，同側內角 ∠B = 110°"],["對角線互相平分","兩對角線互相平分，交點為對稱中心","OA = OC 且 OB = OD；將平行四邊形分成四個面積相等的小三角形"],["一組對邊平行且相等","判別為平行四邊形的充要條件之一","若 AB // CD 且 AB = CD，則四邊形 ABCD 必為平行四邊形"],["兩組對邊分別平行","平行四邊形的原始定義","AB // CD 且 AD // BC；常用於坐標系中向量或中點坐標推求第四頂點"]]);
add('math-24', "特殊四邊形：矩形、菱形、正方形、梯形與箏形", [["矩形（長方形）","四個角皆為直角，對角線等長且互相平分","平行四邊形只要「一角為直角」或「對角線等長」即為矩形"],["菱形","四邊皆等長，對角線互相垂直平分且平分內角","菱形面積 = 兩對角線乘積 / 2；平行四邊形「鄰邊等長」即為菱形"],["正方形","兼具矩形與菱形所有性質（四角直角、四邊等長、對角線垂直平分且等長）","正方形既是矩形也是菱形，為正四邊形"],["等腰梯形與箏形","等腰梯形兩腰等長、底角相等、對角線等長；箏形一對角線為對稱軸垂直平分另一對角線","梯形中線長 = (上底 + 下底) / 2；梯形面積 = 中線長 × 高"]]);
add('math-17', "圓的角度關係：圓心角、圓周角與弦切角", [["圓心角與弧度","圓心角頂點在圓心，其角度度數等於所對弧的度數","所對弧為 60°，則圓心角 ∠AOB = 60°"],["圓周角定理","圓周角頂點在圓上，其度數等於所對弧度數的一半","同弧所對之圓周角皆相等；半圓上的圓周角恆為直角 90°"],["弦切角性質","頂點在圓上的切線與弦所夾的角，度數等於所夾弧度數的一半","弦切角度數等於其所夾弧所對的圓周角度數"],["圓內接四邊形","四頂點皆在同一圓周上，其「對角互補」（和為 180°）","四邊形 ABCD 內接於圓，則 ∠A + ∠C = 180°，∠B + ∠D = 180°"]]);
add('math-25', "圓與直線、切線性質及兩圓位置關係", [["圓與直線相交關係","比較圓心到直線距離 d 與半徑 r：d < r 交於兩點；d = r 切線；d > r 外離","直線為切線時，切點半徑必垂直該切線（圓心切點半徑垂直切線）"],["圓外一點切線段等長","由圓外一點向圓作兩條切線，切線段等長且連線平分夾角","PA = PB，PO 平分 ∠APB 且 PO 垂直平分弦 AB"],["圓內角與圓外角","圓內角 = (夾弧和)/2；圓外角 = (夾弧差)/2","圓內兩弦交點不是圓心，切忌套用圓心角公式"],["兩圓位置關係","比較連心線長 d 與兩圓半徑 r₁, r₂ 之和差","外離 (d > r₁+r₂)；外切 (d = r₁+r₂)；相交 (r₁-r₂ < d < r₁+r₂)；內切 (d = r₁-r₂)；內離 (d < r₁-r₂)"]]);
add('math-19', "統計圖表與集中量數（平均數、中位數、眾數）", [["算術平均數","所有數值總和除以資料總筆數，極易受極端值拉偏","資料：2, 3, 4, 5, 100；平均數 22.8 無法代表多數群體特徵"],["中位數 (Me)","資料由小到大排序後正中央的數值，不受極端值影響","奇數筆取第 (n+1)/2 筆；偶數筆取第 n/2 筆與第 n/2+1 筆之算術平均數"],["眾數 (Mo)","資料中出現次數最頻繁的數值，適用於類別資料或離散數值","可能無眾數（出現次數皆同），也可能有多個眾數（雙峰分配）"],["次數分配折線圖","橫軸為各組組中點，縱軸為次數，兩端需延伸閉合至相鄰組中點（次數為 0）","累積次數折線圖之累積相對次數達 50% 處對應之橫軸坐標即為中位數估計值"]]);
add('math-27', "盒狀圖與離散量數（全距、四分位距、百分位數）", [["百分位數定義","將 n 筆資料由小到大排序，第 p 百分位數記為 P_p","計算 n × p%：若為整數 k，取第 k 筆與第 k+1 筆平均；若非整數，無條件進位取該整數項"],["四分位數","Q1 = P25（第 25 百分位數）、Q2 = P50（中位數）、Q3 = P75（第 75 百分位數）","將整體資料由小到大等分為四個數量大致相等的區間（各約占 25% 筆數）"],["全距與四分位距 (IQR)","全距 = 最大值 - 最小值；四分位距 IQR = Q3 - Q1","全距易受極端值干擾；IQR 描述中間 50% 資料的分散程度，更具穩定性"],["盒狀圖讀圖原則","由最小值、Q1、Q2、Q3、最大值等五數綜合構成","盒子長度為 IQR，箱內線為中位數；盒子長不代表個數多，而是代表該區間資料分散程度大"]]);
add('chinese-1', "常用修辭與摹寫技巧：譬喻、轉化與感官摹寫", [["譬喻三要素","本體、喻詞（如、像、若、似）、喻體三者具備為明喻","「那雙眼睛像夜空中的繁星」；略去喻詞為隱喻（是、成）"],["轉化修辭","擬人（物化為人）、擬物（人化為物）、形象化（抽象概念具體化）","「春風輕輕撫摸著大地」為擬人；「把愁緒剪成一片片」為形象化"],["感官摹寫","視覺、聽覺、嗅覺、味覺、觸覺等具體感官經驗摹寫","「風裡帶來新翻的泥土的氣息」（嗅覺）；「清脆的鳥鳴」（聽覺）"],["修辭功能","修辭不可脫離文本情意，必須能增強情境描寫與感染力","判斷修辭時需連結文章主旨，非僅背誦名詞定義"]]);
add('chinese-6', "特殊修辭與修辭轉換：轉品、借代與象徵手法", [["轉品詞性變換","字詞在文句中改變原本詞性（如名詞作動詞、形容詞作動詞）","「春風又『綠』江南岸」（形容詞轉動詞使動用法）"],["借代事物特徵","不直接說出本名，借用特徵、標誌或部分代指全體","「千里共『嬋娟』」（借代月亮）；「過盡『千帆』皆不是」（借代船隻）"],["象徵情意寄託","藉由具體物象寄託抽象的思想、情感或精神哲理","「蓮花」象徵出淤泥而不染的君子品格；「白鴿」象徵和平"],["辨析界線","借代是代稱特定事物，象徵則是哲理情感的深化意蘊","「布衣」借代平民（特徵代稱）；「孤雁」象徵遊子飄零（情感投射）"]]);
add('chinese-14', "對比與諷刺修辭：映襯、倒反與層遞技巧", [["映襯修辭","將兩種相反或相對的事理放在一起對照比較，凸顯本質","「朱門酒肉臭，路有凍死骨」反襯貧富懸殊的殘酷社會"],["倒反修辭","言辭表面與作者內心真意相反，多用於諷刺或詼諧調侃","「你可真準時啊，讓大家等了兩個小時！」（表面稱讚實為指責）"],["層遞修辭","依程度深淺、數量多寡或空間大小順序逐層推進","「古之欲明明德於天下者，先治其國；欲治其國者，先齊其家」"],["文本語境檢核","倒反修辭必須配合上下文反差與特定語氣，切勿以字面直解","閱讀考題中先抓說話者立場，再解讀倒反文字之真正諷喻指涉"]]);
add('chinese-4', "圖表訊息轉譯與跨文本閱讀理解策略", [["圖文互轉","將長條圖、折線圖或圓餅圖之數據趨勢轉譯為文字論點","先讀圖表標題、座標軸單位與圖例，再抓極值（最高最低）與轉折點"],["跨文本互證","對照兩篇以上文本，找出共同觀點、分歧立場或互補證據","文本 A 強調經濟發展，文本 B 聚焦生態衝擊，比較兩者論證前提"],["事實與觀點區分","客觀可驗證數據為「事實」；主觀價值評判與推論為「觀點」","「今年降雨量減少 30%」（事實）；「這是近年最嚴重的乾旱危機」（觀點）"],["多元訊息整合","綜合圖表數據與長文敘述，評估作者結論是否具備充分推論支撐","若圖表趨勢僅顯示相關性，不能被文章過度推論為因果必然"]]);
add('english-16', "跨領域長篇閱讀與圖表轉譯 (Informational Texts & Charts)", [["Skimming 略讀大意","快速閱讀文章首尾段、每段首句與小標題，掌握核心主題與主旨","Read topic sentences first to capture the main idea before details."],["Scanning 掃讀細節","帶著關鍵字（數字、專有名詞、年代）在文章與圖表中定位具體資訊","Search for specific data, dates, or keywords without reading every word."],["Graphic Interpretation 圖表判讀","對照文章段落論點與長條圖/表格數據，檢核文字論據是否吻合","Verify whether chart trends support the author’s hypothesis or conclusion."],["Inference & Attitude 語氣推論","從作者選詞（however, shockingly, crucially）推斷其立場態度與寫作意圖","Identify the author's tone: objective, critical, persuasive, or humorous."]]);
add('chinese-8', "語氣判讀與情意抒發（祈使、反詰、推測與感嘆）", [["反詰語氣（激問）","心中已有明確答案，以反問形式加強肯定或否定語氣，答案在問題反面","「何不食肉糜？」（指責無知）；「學而時習之，不亦說乎？」（肯定喜悅）"],["推測與商榷語氣","使用「得無、其、莫非、庶幾、蓋」等詞，表達委婉推想或不確定判斷","「覽物之情，得無異乎？」（難道沒有不同嗎？委婉推論）"],["祈使與命令語氣","使用「願、請、唯、勖」等詞，表達請求、勸勉、期望或嚴肅囑託","「願陛下託臣以討賊興復之效」（懇切請求囑託）"],["感嘆語氣","使用「嗚呼、嗟夫、噫、嘻」等發語詞或嘆詞，抒發強烈悲喜感慨","「嗚呼！師道之不傳也久矣！」（深切痛惜感嘆）"]]);
add('chinese-12', "實用應用文規約：書信、便條、柬帖與題辭格式", [["書信稱謂與提稱語","稱長輩用「尊鑒、道鑒」；稱平輩用「台鑒、大鑒」；稱晚輩用「如晤、青睞」","對父母提稱語用「膝下、膝前」；切忌對尊長用平輩提稱語"],["書信結尾祝詞與署名","對長輩祝詞用「敬請 福安、叩請 金安」；署名後長輩用「叩上、敬上」，平輩用「謹啟」","信封外中欄啟封詞是寫給郵差或送信人看的，尊長寫「安啟、福啟」，不可寫「敬啟」"],["柬帖請柬規範","婚宴請柬註明時間（席設）、地點、新人姓名與家長敬邀","「恕敬不敏」為婉拒之詞；「準時入席」注意席設時間規範"],["常見題辭分類","祝壽（椿萱並茂、齒德俱尊）；祝婚（百年好合、琴瑟和鳴）；哀輓（駕鶴西歸、音容宛在）","「桃李春風」祝教育界；「妙手回春」祝醫界；題辭對象性別身分切勿張冠李戴"]]);
add('chinese-9', "近體詩格律體制：五言/七言絕句與律詩規範", [["句數與字數","絕句四句（五絕 20 字、七絕 28 字）；律詩八句（五律 40 字、七律 56 字）","超過八句者為排律；近體詩字數嚴格固定，不可任意增減長短句"],["押韻規範","偶數句（2, 4, 6, 8 句）押平聲韻，首句可押可不押，第三句、奇數句必不押韻","一韻到底，不可換韻；押韻字必須同韻部（平水韻）"],["律詩對仗要求","律詩三四句（頷聯）與五六句（頸聯）必須嚴格對仗（詞性相對、句式相同）","首聯（一二句）與尾聯（七八句）通常不對仗；絕句則不強制要求對仗"],["平仄黏對規則","「一三五不論，二四六分明」；避免犯孤平與三平調","二四六字平仄位置固定；出句與對句之平仄必須相對"]]);
add('chinese-10', "宋詞與元曲體制音律：詞牌、曲牌與長短句", [["詞牌與曲牌","詞牌（如水調歌頭、念奴嬌）規定詞的字數、句式、平仄與押韻，與內容題目無必然關係","辛棄疾〈破陣子·為陳同甫賦壯詞以寄之〉中，「破陣子」為詞牌，「為陳同甫...」為題目"],["詞的句式與押韻","長短句，又稱「詩餘」或「倚聲」；平仄可依詞調譜曲，有的詞牌可平仄通押或換韻","通常分上下兩片（雙調），少數為單調或三疊"],["散曲體制（小令與套數）","元曲包括雜劇與散曲；散曲分單首之「小令」與同宮調多曲相連之「套數」","馬致遠〈天淨沙·秋思〉為散曲中的小令；曲牌為「天淨沙」"],["曲可加襯字","曲在規定的曲牌正字之外，可靈活加入「襯字」，不影響曲譜節拍，使口語更生動","詞不可加襯字，曲可以加襯字，這是詞與曲體制上極重要之辨識關鍵"]]);
add('english-4', "形容詞與副詞比較級與最高級規則", [["單音節規則變化","單音節字尾加 -er / -est（tall → taller → tallest；nice → nicer → nicest）","子音+短母音+子音重複字尾：big → bigger → biggest；字尾 y 變 i+er：happy → happier"],["多音節與 -ly 副詞","三音節以上形容詞及以 -ly 結尾之副詞前加 more / most","more expensive / most expensive；more carefully / most carefully"],["不規則變化","good/well → better → best；bad/badly → worse → worst；many/much → more → most","far → farther（距離更遠）/ further（程度更深）；little → less → least"],["比較句型搭配","比較級搭配 than；最高級前必加 the 並搭配範圍介系詞 (of all / in the class)","He runs faster than I do. / She is the tallest student in our school."]]);
add('english-10', "原級比較 (as...as) 與複合比較結構", [["原級同等比較","as + 形容詞/副詞原級 + as（和...一樣）","He is as smart as his brother. / She sings as beautifully as a bird."],["否定同等比較","not as/so + 原級 + as（不及...；不如...）","This book is not as interesting as that movie. (That movie is more interesting.)"],["越來越... (More and more)","單音節用比較級 and 比較級；多音節用 more and more + 原級","It is getting colder and colder. / The city is becoming more and more crowded."],["越...就越... (The + 比較級)","The + 比較級 + S + V, the + 比較級 + S + V","The more you practice, the better you will speak English."]]);
add('english-7', "五大基本句型與補語辨析 (S+V, S+V+O, S+V+C, S+V+O+O, S+V+O+C)", [["S + V（完全不及物）","動詞自身意思完整，不需受詞也不需補語","Birds fly. / The baby cried loudly.（loudly 為副詞修飾動詞，非受詞）"],["S + V + C（不完全不及物）","連綴動詞需主詞補語 (SC) 補充說明主詞身分或狀態","She looks happy.（happy 為形容詞補語）；He became a teacher."],["S + V + O（完全及物）","動詞需接受動作的對象（受詞 O）","They play basketball every Sunday. / I bought a new computer."],["S+V+O+O vs S+V+O+C","雙賓動詞有兩個受詞（間接受詞人 + 直接受詞物）；受詞補語修飾受詞狀態","He gave me a book (me ≠ a book, S+V+O+O)；They made him captain (him = captain, S+V+O+C)"]]);
add('english-8', "特殊句型：祈使句、感嘆句與附加問句規則", [["祈使句規範","省略主詞 You，以原形動詞開頭；否定句用 Don't + 原形動詞","Open the door, please. / Don't be late for school again."],["感嘆句結構","What + a/an + adj + 單數名詞 + S + V! / How + adj/adv + S + V!","What a beautiful girl she is! / How fast he can run!"],["附加問句前肯後否","直述句肯定，附加問句用否定縮寫；直述句否定，附加問句用肯定","You are a student, aren't you? / She didn't go, did she?"],["特殊附加問句","祈使句附加問句用 will you?；Let's 開頭用 shall we?；I am... 用 aren't I?","Let's go for a walk, shall we? / Have a seat, will you?"]]);
add('biology-1', "細胞構造與動植物細胞比較", [["細胞核與遺傳","含遺傳物質 DNA，為細胞生命活動的控制中心","紅血球成熟後無細胞核；原核生物（細菌）無核膜包覆之細胞核"],["細胞壁與形狀維持","植物、真菌及細菌具細胞壁（植物成分為纖維素），動物細胞無細胞壁","植物細胞浸入清水膨脹而不破裂；動物紅血球浸入清水會吸水膨脹破裂"],["葉綠體與粒線體","粒線體為動植物共有的「能量發電廠」（呼吸作用生成 ATP）；葉綠體僅綠色植物進行光合作用","植物非綠色細胞（如根部細胞、洋蔥鱗葉表皮細胞）無葉綠體，但皆有粒線體"],["液胞大小差異","成熟植物細胞具大型中央液胞（儲存水分與廢物並維持膨壓）；動物細胞液胞細小短暫","顯微鏡觀察洋蔥表皮細胞與口腔皮膜細胞，前者具明顯細胞壁且形狀規則，後者不規則"]]);
add('biology-7', "物質進出細胞機制：擴散作用與滲透作用", [["簡單擴散作用","分子由高濃度往低濃度自然淨移動，不消耗能量 (ATP)","氣體分子（O₂、CO₂）及脂溶性物質（甘油、脂肪酸）可直接穿透磷脂質雙層"],["促進性擴散（便利性擴散）","由高濃度往低濃度，需細胞膜上「膜蛋白（通道蛋白/載體蛋白）」協助，不耗能","葡萄糖、胺基酸及各類帶電礦物質離子進出細胞之主要被動運輸方式"],["滲透作用水分子移動","水分子穿透半透膜由低溶質濃度（高水分子濃度）往高溶質濃度移動","將紅血球置入濃鹽水（高滲透壓），水分滲出細胞而萎縮；置入清水（低滲透壓）膨脹破裂"],["主動運輸條件","逆著濃度梯度（低濃度往高濃度），必須消耗細胞能量 (ATP) 且需載體蛋白","小腸絨毛細胞主動吸收剩餘葡萄糖；神經細胞鈉鉀幫浦維持膜電位平衡"]]);
add('biology-4', "神經系統傳導與反射弧運作機制", [["中樞神經系統","大腦（意識、感覺、思考、隨意運動）；小腦（肌肉協調、平衡）；腦幹（生命中樞：心跳、呼吸、血壓）","酒醉走路搖晃主要影響小腦平衡協調；腦死判定係因腦幹功能喪失"],["意識動作傳導路徑","受器 → 感覺神經元 → 脊髓 → 大腦（產生意識決定） → 脊髓 → 運動神經元 → 動器","看到紅燈踩煞車：大腦意識參與，反應時間較長，可透過練習縮短時間"],["反射弧神經路徑","受器 → 感覺神經元 → 反射中樞（脊髓或腦幹） → 運動神經元 → 動器","膝反射、縮手反射中樞在脊髓；眨眼、唾液分泌、瞳孔縮放中樞在腦幹；不經大腦即刻完成保護"],["感覺形成在大腦","受器僅接受刺激產生神經衝動，真正的痛覺、視覺、聽覺皆在大腦感覺區形成","手被針扎先縮手（反射），隨後大腦才感覺到劇痛並喊叫（意識傳導上行至大腦）"]]);
add('biology-13', "內分泌系統激素與負回饋調節機制", [["內分泌腺體特性","無導管腺體，分泌激素（荷爾蒙）直接釋入血液循環，作用於特定目標器官（標的細胞）","外分泌腺（如汗腺、唾液腺、胰液消化導管）具導管；胰臟兼具外分泌與內分泌功能"],["血糖恆定雙重調節","進食後血糖升高 → 胰島分泌「胰島素」促使血糖轉化為肝醣儲存；飢餓時分泌「升糖素」分解肝醣","腎上腺素在緊急壓力時分泌，亦可迅速升高血糖以應付危急戰鬥或逃跑反應"],["甲狀腺素與腦垂腺","腦垂腺分泌促甲狀腺素 (TSH) 調節甲狀腺；甲狀腺素分泌過多負回饋抑制 TSH","幼年缺乏甲狀腺素導致呆小症；成年分泌過多引發甲狀腺機能亢進（代謝過快、消瘦突眼）"],["神經與內分泌比較","神經調節以電訊號與神經傳導物質傳遞，速度快、範圍局限、作用短暫","內分泌調節以血液運輸化學信號，反應較慢、作用範圍廣泛且持續時間長久"]]);
add('biology-6', "生物圈層級架構與群集種間互動關係", [["個體、族群與群集","族群（同一時間、地點同種生物個體總和）；群集（同一區域內所有生物族群總和）","七股潟湖的所有黑面琵鷺為一個「族群」；潟湖內的所有鳥類、魚類、紅樹林構成「群集」"],["掠食與寄生差異","掠食者殺死獵物取食；寄生者生活於寄主體內外吸收養分，通常不立即殺死寄主","獅子捕食斑馬為掠食；絛蟲寄生人體腸道、跳蚤寄生狗皮毛為寄生"],["互利共生與片利共生","互利共生雙方皆獲益 (+, +)；片利共生一方獲益另一方無害無益 (+, 0)","小丑魚與海葵、豆科植物與根瘤菌為互利共生；鮣魚吸附鯊魚腹部為片利共生"],["種間競爭排擠","兩個族群利用相同有限資源（食物、棲所、陽光），生存曲線互相壓制 (-, -)","兩同屬草履蟲培養於同一試管，生態棲位重疊導致其中一種最終滅絕（競爭排除原理）"]]);
add('biology-12', "生態系能量流動與碳氮物質循環", [["能量單向流動","太陽能 → 生產者（光合作用） → 初級消費者 → 次級消費者；能量沿食物鏈傳遞無法循環","能量金字塔每上升一個營養階層約僅保留 10% 能量，其餘 90% 轉為呼吸散熱或未被同化逸散"],["物質循環不滅","碳、氮、水等化學元素在非生物環境與生物體之間反覆循環利用","生物呼吸釋出 CO₂，生產者光合作用固定 CO₂；死亡遺體經分解者分解回歸大地"],["氮循環與微生物","大氣中 N₂ 需經「固氮菌」（如根瘤菌）轉化為氨/銨鹽，再經硝化細菌轉為硝酸鹽供植物吸收","脫氮細菌在缺氧土壤中將硝酸鹽還原為氮氣釋回大氣，完成氮循環封閉閉環"],["生物放大作用（生物累積）","重金屬（鉛、汞）或脂溶性農藥 (DDT) 無法排出與分解，隨食物鏈階層上升急遽濃縮","浮游生物濃度最低，頂級肉食掠食者（如猛禽、大型齒鯨）體內累積毒素濃度最高"]]);
add('physics-3', "光的折射規律與凸透鏡成像光學", [["折射定律與光速","光由光速快介質（空氣）斜射入光速慢介質（水/玻璃），折射光線偏向法線（入射角 > 折射角）","筷子斜插水中看似向上折斷；池水看起來比實際深度淺，皆因光線折射進入人眼所致"],["三條關鍵光線","平行主光軸光線折射後通過焦點；通過透鏡中心光線方向不變；通過焦點光線折射後平行主軸","凸透鏡成像之幾何作圖只需繪出其中任意兩條折射光線交點，即可求出像的位置與大小"],["物距與實像大小","物距 > 2f 成倒立縮小實像（照相機原理）；物距 = 2f 成倒立等大實像；f < 物距 < 2f 成倒立放大實像（投影機）","實像皆為折射光線實際匯聚而成，能以紙屏承接，且在透鏡異側恆呈倒立"],["虛像與放大鏡條件","物距 < f 成正立放大虛像（放大鏡原理），像在物體同側","虛像為折射發散光線之反向延長線交會而成，無法在紙屏承接，必須直接用人眼透鏡觀察"]]);
add('physics-14', "面鏡反射與透鏡光學成像綜合比較", [["平面鏡反射成像","反射定律（入射角 = 反射角）；成「等大、正立、左右相反」的虛像，物距 = 像距","身高 160 cm 的人，只需 80 cm（身高一半）的直立平面鏡即可看到全身像"],["凹透鏡光學特性","對光線具發散作用，不論物體放在鏡前何處，恆成「正立、縮小、虛像」於物同側","近視眼鏡鏡片即為凹透鏡，利用發散作用將眼球過早匯聚的光線焦點後移至視網膜上"],["凹面鏡與凸面鏡","凹面鏡具匯聚作用（手電筒反射罩、太陽爐）；凸面鏡具發散廣角視野功能（道路轉角反光鏡、後照鏡）","凸面鏡所成之像恆為正立縮小虛像，可大幅擴大後方可視安全範圍"],["近視與遠視矯正","近視眼球軸過長或水晶體折光力過強，像落在視網膜「前方」，戴「凹透鏡」矯正","遠視像落在視網膜「後方」，戴「凸透鏡」匯聚矯正；老花眼成因則為睫狀肌彈性疲乏調節力減退"]]);
add('physics-5', "牛頓運動定律與慣性現象判定", [["牛頓第一定律（慣性）","合力為零時，靜者恆靜，動者恆作等速度直線運動；物體維持原有運動狀態的特性稱為慣性","汽車緊急煞車時乘客身體向前傾；甩動體溫計使水銀柱回位；拍打衣服抖落灰塵皆為慣性實例"],["牛頓第二定律 (F=ma)","物體受外力合力作用時，產生同方向加速度；a 與合力成正比，與質量 m 成反比","1 N 定義：使 1 kg 物體產生 1 m/s² 加速度之合力；合力加倍則加速度加倍"],["牛頓第三定律（作用力與反作用力）","大小相等、方向相反、作用在同一條直線上，且同時產生、同時消失","作用在不同物體上（受力對象不同），因此兩力絕對不能在同一受力圖中互相抵消"],["平衡力 vs 反作用力","一對平衡力作用在「同一個物體」上且合力為零；作用與反作用力作用在「兩個相異物體」上","書本重力與桌面支持力（同作用於書本，為平衡力）；書本壓桌與桌推書（互為作用與反作用力）"]]);
add('physics-10', "力的平衡條件與摩擦力判別法則", [["二力平衡條件","大小相等、方向相反、作用在同一直線上，且作用在「同一個物體」上，合力為零","懸掛靜止的吊燈受重力與繩子拉力，兩力共線反向等大，吊燈維持靜力平衡"],["靜摩擦力 (fs)","物體受外力推動但仍維持靜止時存在，大小隨外力增減而改變，方向與相對運動趨勢相反","用 5 N 推桌子桌不動，靜摩擦力即為 5 N；改用 10 N 推桌仍不動，靜摩擦力增至 10 N"],["最大靜摩擦力 (fs,max)","即將推動瞬間的摩擦力臨界值，與正向力 N 成正比 (fs,max = μs·N)，與接觸面積大小無關","在水平面上放置木塊，正向力等於木塊重力；若上方加壓重物，最大靜摩擦力隨正向力等比例增加"],["動摩擦力 (fk)","物體在接觸面滑動時的阻力，大小固定 (fk = μk·N)，通常小於最大靜摩擦力且與滑動速度無關","木塊滑動後只需較小的推力即可維持等速度滑行；流體潤滑與滾動軸承可大幅減小摩擦力"]]);
add('physics-6', "功與功率運算及簡單機械原理", [["做功的物理定義","W = F · s · cosθ；力與位移同向做正功 (W>0)；反向做負功 (W<0)；垂直做功為零 (W=0)","背書包水平等速行走，垂直向上支撐力不做功；手提水桶等速上樓梯，向上拉力做正功"],["功率物理意義","功率 P = W / t，代表單位時間內所做的功，即做功的快慢速率","單位為瓦特 (W = J/s)；1 馬力約 746 W；兩起重機做相同的功，耗時較短者輸出功率較大"],["槓桿原理與力矩平衡","力矩 L = 力 × 力臂；順時針力矩 = 逆時針力矩時維持轉動平衡","省力槓桿（動力臂 > 抗力臂，如開瓶器、剪鐵皮剪刀）；費力槓桿（動力臂 < 抗力臂，如鑷子、掃帚）"],["機械功不省原則","使用任何輪軸、滑輪、斜面等簡單機械均無法省功；省力必費距離，省距離必費力","斜面高度 h、長度 L：拉力 F = W·(h/L)，斜面越平緩 (L 越大) 越省力，但推動距離等比例增加"]]);
add('physics-15', "動能、重力位能與力學能守恆定律", [["動能公式與特性","Ek = (1/2)mv²；動能與質量 m 成正比，與運動速率 v 的平方成正比","汽車車速由 30 km/h 增至 60 km/h（速度變 2 倍），煞車時所需煞車距離將暴增為 4 倍"],["重力位能差","Ep = mgh；位能具有相對性，必須先選定零位能參考基準面，位能變化量 ΔEp 則為絕對","自 10 公尺高掉落至 2 公尺處，重力做功 W = mgΔh = mg(8)，重力位能減少並完全轉化為動能"],["力學能守恆條件","物體運動過程中僅受「保守力（重力、彈力）」做功時，力學能 E = Ek + Ep 恆保持常數","自由落體、單擺擺動、光滑斜面下滑；最高點位能最大動能為零，最低點動能最大位能最小"],["摩擦耗散與總能守恆","若有空氣阻力或接觸面摩擦力做負功，部分力學能轉化為熱能（內能），總能量依然守恆","人溜滑梯滑至底端，減少的重力位能大於增加的動能，差值等於摩擦生熱所散逸之能量"]]);
add('physics-8', "流體靜壓力與大氣壓力測量", [["液體壓力公式","P = ρ · g · h（在同一均勻不可壓縮液體中，液壓僅與垂直深度 h 及液體密度 ρ 有關）","液壓無特定方向，任一點向四面八方壓力皆相等且垂直於容器接觸面；與容器形狀寬窄無關"],["連通管原理與帕斯卡定律","連通管各管液面在靜止時等高；密閉流體任一點所受壓力增量，等值傳遞至流體各處","液壓千斤頂：小活塞施小力 F₁/A₁，在大活塞 A₂ 產生巨大輸出推力 F₂ = F₁·(A₂/A₁)"],["托里切利實驗","大氣壓力支撐 76 cm 汞柱高 (76 cm-Hg = 1 atm ≈ 1013 hPa = 1033.6 gw/cm²)","水銀柱上方為接近真空之「托里切利真空」；若將玻璃管傾斜，水銀柱垂直高度仍維持 76 cm"],["大氣壓力隨高度變化","海拔高度越高，上方大氣柱越稀薄，氣壓隨高度上升而遞減；高山上水的沸點降低","在平地密封的洋芋片包裝袋，帶到合歡山高海拔地區時，因外界氣壓減小而劇烈膨脹"]]);
add('physics-9', "阿基米德浮力原理與物體沉浮條件", [["阿基米德原理","物體在流體中所受向上浮力，等於其所排開流體的重量：B = ρ液 · V排 · g","物體在空氣中重 W，浸入水中秤得視重 W'，則浮力 B = W - W'（視重減輕量）"],["沉體浮力條件","物體密度大於液體密度 (ρ物 > ρ液)，物體下沉至底，此時排開體積等於物體全部體積 (V排 = V物)","鐵塊沈入水中：浮力 B = ρ水 · V物 < W鐵；繼續往深水處下沉，只要 V排 不變則浮力不變"],["浮體平衡條件","物體密度小於液體密度 (ρ物 < ρ液)，物體漂浮平衡，向上浮力剛好等於物體總重 (B = W物)","木塊浮於水面：ρ水 · V排 · g = ρ木 · V物 · g；露出液面體積與液體密度成反比"],["同一物體不同液體漂浮","同一艘輪船自淡水河駛入大海（海水密度較大），浮力皆等於船重維持不變，但在海水中吃水較淺","漂浮物體在各液體中所受浮力相同；密度越大的液體中，浸入之 V排 越小"]]);
add('chemistry-1', "純物質與混合物物理化學性質辨識", [["純物質特性","具固定的組成成分與恆定的物理性質（固定熔點、沸點、密度）","純水在 1 atm 下沸點恆為 100°C；金剛石、蔗糖、氧氣皆為純物質"],["元素與化合物","元素無法以普通化學方法再分解（如鐵 Fe、硫 S）；化合物由兩種以上元素化合而成（如鹽 NaCl、水 H₂O）","化合物的性質與其組成元素的單質性質完全不同（如金屬鈉與氯氣劇毒，化合為食鹽無毒）"],["混合物性質可變","由兩種以上純物質依任意比例物理混合而成，無固定熔沸點，保留各組成分自身特性","食鹽水、空氣、黃銅合金；鹽水濃度越高，沸點越高且凝固點越低"],["物理變化 vs 化學變化","物理變化本質不變、分子不破壞（如三態變化、溶解）；化學變化產生新物質、伴隨能量吸放","乾冰昇華、水結冰為物理變化；鐵生鏽、木材燃燒、光合作用為化學變化"]]);
add('chemistry-4', "混合物分離方法原理（過濾、蒸發、結晶、層析）", [["過濾法原理","利用顆粒孔徑大小差異，孔隙允許液體與溶解粒子通過，截留不溶性固體顆粒","分離沙子與食鹽水混合液；漏斗濾紙潤濕貼緊壁面，濾液沿玻璃棒緩緩倒入"],["蒸發結晶與蒸餾","利用沸點不同；蒸發皿加熱除去揮發性溶劑回收結晶溶質；蒸餾則冷凝收集低沸點揮發蒸氣","海水曬鹽利用蒸發結晶；釀酒濃縮乙醇利用酒精沸點 (78°C) 低於水 (100°C) 進行蒸餾分離"],["萃取與分液","利用溶質在兩種互不相溶的溶劑中「溶解度差異」進行轉移分離","用碘酒加己烷振盪萃取，紫紅色碘分子大量轉移至上層有機己烷相中"],["濾紙色層分析（層析法）","利用各組分對固定相（濾紙纖維）之吸附力及對移動相（展開劑）之溶解度移動速度差異","將彩色水性筆墨水印點在濾紙底端，浸入水中展開，可分離出多種不同顏色的色素斑點"]]);
add('chemistry-6', "常見有機化合物官能基與化學特性（烴、醇、酸、酯）", [["烴類（碳氫化合物）","僅含碳與氫兩元素，難溶於水、燃燒生成 CO₂ 與 H₂O；烷類為飽和烴","甲烷 (CH₄) 為天然氣主成分；丙烷 (C₃H₈) 與丁烷 (C₄H₁₀) 為液化石油氣瓦斯主成分"],["醇類特性","含羥基 (-OH) 官能基，小分子醇類可與水完全互溶，非電解質水溶液呈中性","乙醇 (C₂H₅OH) 常用於消毒 (75%) 與飲料；甲醇 (CH₃OH) 具神經劇毒，誤飲會失明甚至致死"],["有機酸與羧基","含羧基 (-COOH) 官能基，溶於水能微弱解離出 H⁺，為弱電解質，可使石蕊試紙變紅","乙酸又稱醋酸 (CH₃COOH)，具刺鼻酸味；甲酸又稱蟻酸 (HCOOH)，存在於螞蟻蜂類叮咬毒液中"],["酯化反應與酯類","有機酸 + 醇類 ⇄（濃硫酸催化加熱）酯類 + 水；具水果花芳香氣味、密度小於水且難溶於水","乙酸 + 乙醇 ⇄ 乙酸乙酯 + 水；濃硫酸作為催化劑兼脫水劑，促進平衡向右進行"]]);
add('chemistry-12', "聚合物分類與天然合成材料特性", [["天然聚合物","生物體內自然合成的大分子聚合物，由單體重複聚合而成","蛋白質（單體為胺基酸）、澱粉與纖維素（單體為葡萄糖）、天然橡膠"],["鏈狀聚合物（熱塑性）","分子結構為長鏈狀，加熱易熔化軟化，具延展性，冷卻後固化，可反覆加熱回收加工","聚乙烯 (PE 塑膠袋)、聚苯乙烯 (PS 保麗龍)、聚氯乙烯 (PVC 水管)"],["網狀聚合物（熱固性）","長鏈分子間具有牢固共價橫鍵交聯成三維網狀，耐高溫、受熱不熔化只會炭化分解，無法回收重塑","酚醛樹脂（電木插座、開關外殼）、美耐皿餐具、環氧樹脂"],["合成纖維特性比較","耐綸（尼龍，聚醯胺纖維，強韌耐磨彈性佳）；聚酯纖維（排汗快乾抗皺不易縮水）","天然棉麻透氣吸汗易起皺；天然羊毛保暖但縮水遇熱變性；混紡技術兼具兩者優點"]]);
add('chemistry-7', "化學反應速率與碰撞學說（溫度、表面積、催化劑）", [["有效碰撞條件","反應物粒子必須發生碰撞，且碰撞時「能量須大於低限活化能」且「碰撞方向位向正確」","反應速率定義為單位時間內反應物濃度的消耗量，或生成物濃度的增加量"],["反應物濃度與表面積","濃度越高或固體顆粒越細（接觸表面積越大），單位體積內粒子碰撞頻率越高，反應速率越快","粉末狀碳酸鈣與鹽酸反應速率遠快於大理石塊；麵粉廠粉塵飛揚極易引發粉塵爆炸"],["溫度對速率影響","溫度升高使粒子平均動能增加，具足夠能量跨越活化能門檻的「有效碰撞分子百分比」急劇上升","一般化學反應溫度每上升 10°C，反應速率約提高 2 至 3 倍；冷藏食物可減緩細菌滋生變質"],["催化劑（觸媒）機制","改變反應途徑以「降低反應活化能」，同時加快正逆反應速率，但「絕不改變化學平衡位置與產率」","雙氧水製氧加入二氧化錳 (MnO₂) 催化分解；人體各類生物酵素催化代謝維持生命運作"]]);
add('chemistry-8', "化學平衡狀態與勒沙特列原理應用", [["動態平衡定義","在密閉系統中，正反應速率等於逆反應速率 (r正 = r逆 > 0)，巨觀下各物質濃度不再改變","達到平衡時反應並未停止；反應物與生成物之濃度保持定值，但不代表彼此濃度相等"],["勒沙特列原理","平衡系統受外在因素（濃度、壓力、溫度）干擾時，系統必向「減弱該外加干擾」方向移動","增加反應物濃度，平衡向正方向移動；減少生成物濃度，平衡亦向正方向移動以補充生成物"],["溫度改變對平衡位移","吸熱反應升溫向右移動；放熱反應升溫向逆方向（左）移動","二氧化氮與四氧化二氮平衡：2NO₂ (紅棕色) ⇄ N₂O₄ (無色) + 熱；浸入熱水顏色變深，冰水變淡"],["壓力與催化劑對平衡影響","加壓使氣體平衡向「氣體總係數較小（氣體莫耳數少）」方向移動；兩側氣體係數相等加壓不位移","催化劑同等比例加快正逆反應速率，能提早達到平衡，但絕對無法使平衡發生任何移動"]]);
add('earth-2', "水循環、地下水補注與水資源永續利用", [["水循環動力與路徑","太陽輻射能與重力驅動：蒸發、蒸散、凝結成雲、降水、地表逕流與地下滲透","海洋是全球水循環最大的蒸發源與蓄水庫；水循環在地球各圈層中維持全球水分總量恆定"],["地下水面與地層結構","含水層（孔隙大滲透性佳之砂礫石層）；不透水層（緻密黏土層）；地下水面隨降雨乾濕季升降","受壓地下水夾在兩不透水層之間；若受壓水面高於地表井口，鑿井後自動噴出形成自流井"],["地層下陷與海水倒灌","長期超抽地下水導致含水層顆粒間隙水壓喪失，黏土層被上覆岩層重壓夯實，沉降無法復原","臺灣西南沿海養殖漁業超抽地下水造成地層下陷、海水倒灌鹽化農田、排水不良暴雨淹水"],["水資源永續管理","臺灣降雨豐沛但地形陡峻、河短流急，加上降水乾濕季分布不均，人均可用水量低屬缺水地區","興建水庫蓄水、水土保持植被涵養水源、推動污水再生水回用與海水淡化等永續策略"]]);
add('earth-6', "地表營力作用與沉積岩三大岩石循環", [["風化與侵蝕搬運","風化（原地物理崩解與化學蝕變分解）；侵蝕（流水、風、冰川、波浪將岩屑剝蝕搬離原地）","高山受水反覆結冰凍裂為物理風化；石灰岩被溶有 CO₂ 之酸性地下水溶蝕為化學風化"],["河流三大作用地形","上游侵蝕為主（V 型谷、瀑布）；中游搬運為主；下游沉積為主（沖積扇、氾濫平原、三角洲）","顆粒沉積具淘選分層性：流速減慢時粗砂礫石先沉積於上游中游，細粒泥砂黏土運至出海口沉積"],["三大岩類成因辨識","火成岩（岩漿冷卻結晶，如花崗岩、玄武岩、安山岩）；變質岩（高溫高壓再結晶變質，如大理岩、片麻岩）","沉積岩（碎屑沉積物壓密膠結成岩，如砂岩、頁岩、石灰岩），是唯一常含有「古生物化石」的岩類"],["岩石循環動態系統","任何岩石在地底高溫高壓熔融後皆可成岩漿；暴露地表受風化侵蝕再沉積成沉積岩，循環不息","地殼構造運動將深處岩石抬升推至地表，板塊隱沒帶又將地表沉積物帶入地函熔融重新再造"]]);
add('earth-3', "氣團、鋒面交會與臺灣梅雨寒流天氣變化", [["氣團發源與性質","大陸冷氣團（西伯利亞蒙古發源，寒冷乾燥）；海洋暖氣團（太平洋發源，溫暖潮濕）","氣團離開源地移經不同下墊面時，其溫度與濕度會逐漸發生變性與熱量水氣交換"],["冷鋒過境天氣序列","冷空氣主動推擠暖空氣，暖空氣劇烈被迫抬升，形成狹窄積雨雲帶，陣雨降溫風向轉偏北風","臺灣冬季冷鋒南下通過時，氣溫驟降伴隨東北季風增強，迎風面北部東北部降雨濕冷"],["暖鋒與滯留鋒特性","暖鋒（暖空氣主動爬升於冷空氣之上，大範圍層狀雲連續小雨）；滯留鋒（冷暖勢均力敵徘徊）","臺灣每年五六月梅雨季即由巴士海峽北抬之滯留鋒面滯留盤據造成，常伴隨中尺度強對流豪雨"],["寒流與輻射冷卻效應","強烈大陸冷氣團南下配合晴朗無雲夜間，地表長波輻射熱量散失劇烈形成逆溫輻射冷卻","冬季清晨西南部空曠平原常降至 10°C 以下極低溫，農漁業需嚴防霜害與寒害凍死魚苗"]]);
add('earth-9', "氣壓系統、颱風結構與氣象衛星雲圖判讀", [["高低氣壓空氣流動","北半球高氣壓中心空氣下沉，地面順時針向外輻散（天氣晴朗乾燥）；低氣壓中心空氣上升逆時針向內輻合（陰雨天）","熱空氣上升膨脹冷卻易達飽和凝結成雲降雨；下沉氣流絕熱壓縮增溫使水氣蒸發雲消霧散"],["颱風形成熱力條件","發源於熱帶高溫洋面 (海溫 > 26.5°C) 的強烈熱帶低氣壓，巨大潛熱釋放為其旋轉動能來源","颱風眼區氣流下沉無風無雨；颱風眼牆附近上升氣流最強烈，為風雨最狂暴的核心區域"],["衛星雲圖判讀","可見光雲圖（利用雲層反射太陽光，夜間無法拍攝，雲層越厚越白）；紅外線雲圖（感應雲頂紅外熱輻射）","紅外線雲圖中雲頂溫度越低表示對流雲發展越高越旺盛，在圖像上顯示為強烈的亮白色"],["臺灣颱風災害防禦","颱風登陸受中央山脈地形破壞結構減弱，但迎風面受地形抬升降下極端地形雨致災（土石流與山洪）","引進西南氣流常使中南部山區在颱風遠離後持續降下超大豪雨，防災戒備切不可鬆懈"]]);
add('earth-10', "月球公轉軌道、月相盈虧與日食月食天象", [["月球自轉公轉同步","月球自轉週期等於繞地公轉週期（約 27.3 天），受潮汐鎖定，在地球上永遠只能看見同一面","月球面向地球的半球受陽光照射比例每日改變，產生由新月到滿月的規律月相週期（朔望月約 29.5 天）"],["四大代表月相判讀","初一朔（月在日地中間，不可見）；初七八上弦月（西半亮半圓）；十五望滿月（整面亮）；廿二三下弦月（東半亮）","上弦月正午升起半夜落入西方；滿月傍晚自東方升起整夜可見；下弦月半夜升起中午西落"],["日食條件與類型","月球運行至日地中間（朔）且三者排成一直線，月球本影落在地表產生日食（日全食、日環食、日偏食）","日食僅在地球白晝局部本影區域可見，月球視直徑隨近地點遠地點微幅改變決定全食或環食"],["月食形成與紅月亮","地球運行至日月之間（望），月球完全進入地球本影產生月全食，全食時全地球背陽半球皆可見","月全食時陽光穿透地球大氣層，波長較短的藍光被散射，只有波長較長的紅光折射進入地影映在月面呈暗紅色"]]);
add('earth-12', "引潮力成因、潮汐漲退週期與大潮小潮變換", [["引潮力物理成因","月球與太陽對地球不同部位引力大小不均勻，以及地球繞共同質心公轉慣性離心力之合力","面向月球側引力最大隆起成滿潮；背向月球側慣性離心力相對占優亦隆起成滿潮，地球兩側同時漲潮"],["半日潮週期規律","地球自轉因月球繞地公轉同向延遲，同地點相鄰兩次滿潮間隔約為 12 小時 25 分鐘","每天漲退潮時間約向後順延 50 分鐘；一天通常經歷兩次漲潮（滿潮）與兩次退潮（乾潮）"],["大潮（朔望大潮）","農曆初一（朔）與十五（望），日地月排成一直線，太陽引潮力與月球引潮力疊加同向最大","潮差（滿潮與乾潮水位差）達到最大；此時滿潮水位特別高，沿海低窪地區需慎防海水倒灌"],["小潮（上弦下弦）","農曆初七八（上弦）與廿二三（下弦），日月對地球夾角約 90°，太陽引潮力抵消部分月球引潮力","潮差達到最小；海釣、潮間帶生態觀察與港口大船進出港吃水導航皆須依潮汐預報規劃"]]);
add('geography-1', "地圖四大要素、經緯網坐標系統與投影定位", [["地圖四大基本要素","圖名（核心主題）、圖例（符號意涵）、方向標（指北針）、比例尺（縮小比例）","未標指北針的地圖預設上方為正北；圖例將地表複雜實體抽象標準化表示"],["經線與緯線特徵","經線連接南北兩極等長之半圓，指示南北向；緯線互相平行之完整圓圈，指示東西向","0° 本初子午線區分東西半球；赤道為 0° 緯線，由赤道向兩極緯線長度漸縮為點"],["時區與國際換日線","地球自轉每小時 15° 經度；全球劃分 24 個時區，以經度 180° 為國際換日線基準","東方時間較早；由西向東跨越換日線減一天，由東向西跨越換日線加一天"],["比例尺大小差異","大比例尺（分母小，範圍小，內容詳細如校園平面圖）；小比例尺（分母大，範圍大，內容簡略如世界地圖）","1:10,000 為大比例尺；1:1,000,000 為小比例尺；求地表實際距離需將圖上公分乘以分母換算"]]);
add('geography-8', "等高線地形圖判讀、地勢坡度與河谷山脊走向", [["等高線基本法則","同一條等高線上各點海拔高度相同；閉合曲線絕不相交不分支（懸崖懸壁除外）","兩相鄰等高線高度差為等高距；等高線越密集表示坡度越陡峭，越稀疏表示地勢越平緩"],["山脊線與山谷線","等高線彎曲凸向海拔低處為「山脊（分水嶺）」；等高線彎曲凸向海拔高處為「山谷（集水區）」","溪流河流必發源並流淌於山谷線內；水往低處流，流向必與等高線垂直向海拔低處奔流"],["鞍部與盆地判別","鞍部（相鄰兩山頭之間的低凹鞍狀地帶）；盆地/窪地（等高線閉合中心高度低於四周且內繪示針線）","盆地中間地勢低窪，四周為山嶺或丘陵環繞，如臺北盆地、埔里盆地"],["地形剖面圖繪製","沿指定剖面線標示與各等高線相交點之海拔高度，垂直投影至坐標紙上連成起伏曲線","剖面圖能直觀展現地表高低起伏，是判斷兩點間是否具通視性（視線無遮擋）的最佳工具"]]);
add('geography-2', "臺灣五大地形分區與板塊構造造山運動", [["板塊交界造山活動","歐亞板塊與菲律賓海板塊持續碰撞擠壓，造成中央山脈隆起與頻繁地震","花東縱谷為板塊擠壓縫合帶縫合線；地震多、地勢高峻、山脈多呈東北－西南走向"],["五大地形分布特徵","山地（占全島面積約 1/3，縱貫中央）；丘陵與台地（分布於山地西側山麓波狀起伏）","平原（西部嘉南平原、彰化平原面積最廣由河流沖積而成）；盆地（斷層陷落或河流侵蝕，如臺北、埔里）"],["海岸地形南北東西對比","北部（岬灣相間沉降岩岸礁岩）；南部（珊瑚礁裙礁隆起海岸）；東部（斷層斷崖海岸水深無沙灘）；西部（沙洲潟湖平直淺灘泥岸）","西部多沙洲潟湖適合水產養殖但缺乏優良天然深水良港；東部臨深海懸崖陡峭陸運困難"],["水土保持與環境衝擊","山高坡陡土石鬆散，地震後遇颱風暴雨極易引發大規模崩塌與土石流災害","過度開發山坡地種植高冷蔬菜、茶葉與果樹，破壞森林植被根系截留水源能力加劇災情"]]);
add('geography-3', "臺灣氣候分區、季風系統與水資源時空分配", [["北回歸線劃分熱帶與副熱帶","北回歸線 (23.5°N) 橫貫嘉義花蓮，以南屬熱帶季風氣候，以北屬副熱帶季風氣候","平地常年溫暖，年均溫在 20°C 以上；冬季受東北季風影響，北部多雨濕冷，中南部晴朗乾旱"],["冬夏季風交替機制","冬季東北季風（發源蒙古大陸冷高壓，吹經東海吸收水氣，北部東北部迎風面多雨）","夏季西南季風（發源印度洋與南海，溫暖潮濕，全島高溫多對流午後雷陣雨，山區降水豐沛）"],["降雨時空極端不均","年降雨量高達 2,500 mm 為世界平均 3 倍，但空間分布山地多平原少、迎風坡多背風坡少","南部地區乾濕季分明（雨季 5-10 月占全年 80% 以上，冬春乾旱嚴重，降雨時間高度集中）"],["水資源調度與枯水挑戰","河川短小流急，降水迅速奔流入海難以蓄存；枯水期河床乾涸出現荒溪型河川","中南部農業與高科技半導體園區需高度依賴曾文、南化等水庫跨流域引水調配與防汛防旱"]]);
add('geography-11', "臺灣人口轉型階段、產業結構變遷與城鄉均衡發展", [["人口成長轉型歷程","由早期高出生率高死亡率，過渡至高出生低死亡（人口暴增），再進入低出生低死亡（少子化與高齡化）","臺灣已進入超高齡社會預警階段，扶養比上升，勞動年齡人口結構逐漸老化萎縮"],["產業結構三級演變","第一級產業（農林漁牧）就業比例大幅下降；第二級產業（製造業）歷經輕工業轉重化再轉高科技半導體","第三級產業（商業、金融、資訊服務業）就業人口與產值占比超過 60% 成為現代經濟主幹"],["城鄉差距與空間失衡","人口與公共資源高度過度集中於臺北、新北、桃園、臺中、高雄等直轄都會區","偏鄉人口外流嚴重、學童少子化廢校、地方產業沒落凋零，產生區域發展失衡困境"],["國土空間活化對策","推動地方創生結合在地特色文化與生態觀光，吸引青年返鄉創業就業","建構高鐵、臺鐵捷運化與環島交通路網，加強偏鄉長照醫療與遠距教育資源數位平權"]]);
add('geography-6', "歐洲自然環境地形地勢、溫帶氣候分區與歐洲聯盟區域整合", [["地形骨架與冰河作用","南部高峻阿爾卑斯褶曲山脈，中部廣闊低緩西歐大平原，北部古老斯堪地那維亞山地","第四紀冰河侵蝕形成挪威峽灣海岸、芬蘭冰蝕湖群（千湖之國）與波德平原冰磧丘陵地形"],["三大溫帶氣候比較","溫帶海洋性（西歐，北大西洋暖流與西風吹拂，終年溫和濕潤年溫差小）","溫帶大陸性（東歐，深居內陸年溫差極大降水集中夏季）；地中海型（南歐，夏乾熱冬溫潤雨，副熱帶高壓夏移籠罩）"],["歐洲聯盟 (EU) 經濟整合","建立單一內部市場，實現商品、人員、勞務與資本自由跨國流動；多數成員國採用單一貨幣歐元 (Euro)","申根公約取消內部邊境檢查；透過共同農業政策與區域基金縮減東西歐區域經濟發展差距"],["當代歐洲面臨挑戰","能源供應安全與綠能轉型代價；難民與非法移民安置融合人權爭議；極端氣候熱浪乾旱常態化","地緣政治局勢緊張促使歐盟深化防衛戰略自主，兼顧經濟競爭力與碳中和永續目標"]]);
add('geography-10', "北美洲自然環境景觀、商品化農業帶與全球經濟樞紐", [["三大地形縱列帶","西部高峻落磯褶曲山系（板塊交界環太平洋地震帶）；中部遼闊中央大平原（密西西比河流域沃野）","東部古老低緩阿帕拉契山脈；北美地形平原暢通無阻，冬季北極寒流可長驅直入南下墨西哥灣"],["氣候分布多樣性","東南部夏熱冬溫副熱帶濕潤氣候；東北部與五大湖區溫帶大陸性濕潤；西岸加州地中海型氣候","落磯山脈背風面（大平原西部）雨量受阻形成溫帶草原與乾燥沙漠氣候，灌溉依賴奧加拉拉地下含水層"],["高度商品化農業專業區","農業高度機械化、資金密集與科技化，形成高度專業化農業帶（小麥帶、玉米帶、乳酪帶、棉花帶）","產量巨大主要供應全球農產品出口市場，受國際期貨價格與全球糧食安全鏈高度波動影響"],["全球金融科技中心","紐約華爾街引領全球資本市場金融體系；加州舊金山灣區矽谷 (Silicon Valley) 匯聚全球頂尖科技創新人才","高度城市化形成波士頓－華盛頓 (Bosh-Wash) 與五大湖區巨型城市群 (Megalopolis)"]]);
add('geography-13', "大洋洲島嶼三大群落生態與極地環境脆弱性保護", [["大洋洲島嶼三大群","玻里尼西亞（多島之意，夏威夷、紐西蘭、復活節島）；美拉尼西亞（黑膚之意，新幾內亞、斐濟）；密克羅尼西亞（微小之意，關島、帛琉）","按島嶼成因分為大陸島（面積大礦產豐）、火山島（地勢高聳土壤肥沃）與珊瑚礁島（低平環礁淡水匱乏）"],["澳洲古老孤立生態","長期孤立於南半球古大陸漂移，演化出獨特古老有袋類動物（袋鼠、無尾熊）與卵生單孔類（鴨嘴獸）","氣候呈半環狀分布，內陸廣大熱帶乾燥沙漠，人口與經濟高度集中於東南沿海溫和濕潤地帶"],["極地環境特徵比較","北極地區（被歐亞與北美大陸包圍的冰凍北冰洋海盆，無常住原住民國家，蘊藏豐富油氣資源）","南極大陸（被南冰洋環繞的高原陸地，覆蓋全球 90% 陸地冰川，平均海拔最高、氣溫最低、風力最強大陸）"],["全球暖化脆弱性衝擊","極地冰川與海冰融化加速全球海平面上升，大洋洲低海拔環礁國家（吐瓦魯、吉里巴斯）面臨滅頂沉沒危機","《南極條約》凍結領土主權主張，規範南極僅能用於和平科學考察目的，嚴禁軍事軍事活動與礦產商業開採"]]);
add('geography-7', "全球化趨勢、全球空間分工與國際經貿組織運作", [["全球化驅動引擎","交通運輸技術革新（貨櫃化海運、噴射民航機）與資通訊網際網絡普及，大幅降低時空阻隔成本","跨國企業在全球尋求最低生產成本與最大消費市場，促進全球供應鏈與價值鏈垂直整合深度分工"],["全球空間分工鏈","先進國家掌握核心技術研發、品牌行銷與金融資本（高附加價值微笑曲線兩端）","開發中國家憑藉廉價勞動力與土地承接代工製造組裝（中間低附加價值製造），造成產業外移空洞化"],["國際經貿三大支柱","世界貿易組織 (WTO，推動降稅消除貿易壁壘建立爭端仲裁機制)；國際貨幣基金 (IMF，維護全球金融穩定救助債務危機)","世界銀行 (World Bank，提供長期低利貸款資助開發中國家基礎建設與減貧工程)"],["反全球化與地緣重組","貧富差距擴大、勞工失業受創引發保護主義抬頭；疫情與地緣政治衝突促使供應鏈縮短推動「友岸外包」","如何在享受全球貿易比較利益優勢的同時，強化國家關鍵戰略產業供應鏈韌性成為核心課題"]]);
add('civics-6', "大眾傳播媒體素養、數位演算法與資訊識讀查證", [["媒體第四權角色","新聞自由受憲法保障，扮演監督政府施政、揭露社會不公、維護公眾知情權的防狗角色","媒體報導應嚴格遵守客觀中立、平衡報導、事實查證原則，避免煽色腥誇大不實報導"],["媒介建構真實批判","媒體呈現的訊息是經過篩選、剪輯、框架與詮釋後建構出的「媒介真實」，並非客觀客觀世界的全貌","受眾需具備「媒體素養」，主動解構新聞產製背後的意識形態、商業利益驅力或特定政治立場"],["演算法同溫層效應","社交媒體演算法依用戶喜好推薦相似觀點內容，導致「過濾泡泡」與「同溫層回音室效應」強化偏見","不同立場群體日趨極化對立，理性公共討論空間遭到壓縮侵蝕，對民主政治理性對話構成嚴峻挑戰"],["假訊息查核查證行動","面對網路爭議訊息遵循「不製造、不輕信、不轉傳」原則，善用第三方獨立事實查核機構","交叉比對多方可信原始消息來源，檢視圖片影音是否經過惡意變造深偽 (Deepfake) 或去脈絡化移花接木"]]);
add('civics-1', "自我認同發展、多元家庭型態與生命階段身心轉變", [["青少年自我認同","艾瑞克森心理社會發展論：青少年期面臨「自我認同 vs 角色混淆」核心心理發展危機","透過同儕互動、興趣探索與價值觀思辨，建立獨立人格與對未來自我的責任感與方向定向"],["多元家庭型態包容","家庭型態日益多元：核心家庭、折衷家庭、單親家庭、隔代教養家庭、重組家庭與同性配偶家庭","家庭的核心價值在於成員間的愛、關懷、支持、陪伴與責任承擔，不以血緣或傳統形式為唯一標準"],["家庭功能五大面向","生育功能、經濟功能、教育與社會化功能、保護與照顧功能、情感慰藉支持功能","現代家庭部分功能已部分轉移由社會機構分擔（如幼兒托育、學校教育、安養機構），但情感功能無可取代"],["家庭衝突溝通因應","兩代間價值觀差異、親子教養觀念分歧或生活習慣摩擦常引發代溝與爭執衝突","運用「我訊息 (I-message)」理性表達自身感受與需求，同理傾聽對方立場，尋求雙贏妥協方案"]]);
add('civics-2', "校園生活民主參與、性別平等意識與學生權利保障", [["學生自治民主實踐","依《教育基本法》與學校自治規章，學生有權組織班會、學生會等自治組織參與校園事務","透過民主程序選拔學生代表、討論公共議題、參與校務會議校服服儀等與學生權益密切相關之規約制定"],["性別刻板印象破除","辨析性別角色期待與刻板印象（如男剛女柔、特定職業性別限制），尊重多元性別特質","性別認同與性傾向屬於個人人格權核心，每個人皆享有免受歧視、霸凌與偏見對待的尊嚴"],["性別平等教育法保護","學校應建構性別友善校園環境，預防並嚴正處理校園性侵害、性騷擾或性霸凌事件","任何教職員工生知悉校園疑似性平事件，依法須於 24 小時內向主管機關進行通報啟動調查機制"],["學生正當權利救濟","學生如認為學校之懲處、輔導措施或其他公權力行政行為違法損害其受教育權或人格權","得依法向學校「學生申訴評議委員會」提出學生申訴；不服申評會決定者，得進一步依法提起訴願及行政訴訟"]]);
add('civics-10', "多元文化價值尊重、文化位階批判與弱勢族群權益", [["文化多元主義價值","尊重不同族群在語言、歷史記憶、宗教信仰、風俗生活習慣上的差異與主體性","各族群文化無優劣貴賤之分，反對主流族群以強勢姿態推行「同化主義」，提倡共存共榮之多元文化論"],["打破文化位階與偏見","主流強勢群體常將自身審美觀、語言腔調或生活型態定為「高雅文明」，貶低少數非主流文化為「落後粗俗」","深刻反思生活中的微歧視 (Microaggression)，消除文化位階霸權，建立平等對話與互惠理解基礎"],["原住民族權利法制保障","《憲法增修條文》第十條明定國家肯定多元文化並積極維護發展原住民族語言及文化","依《原住民族基本法》保障其土地自主權、傳統領域資源利用、母語雙語教育與部落諮商同意權"],["新住民融合與文化平權","推動跨國婚姻新住民生活適應輔導、語言學習與就業培力，鼓勵新住民第二代傳承母語優勢","公立圖書館與大眾傳播媒體應提供多元語文資源，落實憲法保障之文化近用權與文化公民權"]]);
add('civics-3', "現代國家組成要素、主權在民與民主治理基本理念", [["國家四大組成要素","人民（具備該國國籍的公民群體）、領土（領陸、領海 12 浬、領空）、政府（行使國家公權力機關）、主權（對內最高對外獨立統治權）","領土範圍為國家主權行使的空間邊界；主權對內具有至高無上的統治管轄權，對外享有獨立平等不受干涉地位"],["民主政治四大核心原則","民意政治（施政必須反映國民意志）、法治政治（公權力行使依法有據）、責任政治（政策成敗負政治與法律責任）、政黨政治（公平競爭和平政權輪替）","民主國家的正當性基礎來自於「被統治者的同意」，一切國家權力源自於全體國民授權"],["國民主權與公民投票","《憲法》第二條明定「中華民國之主權屬於國民全體」；國民透過選舉罷免行使間接民主代表權","依《公民投票法》透過全國性公投針對重大政策或法律原則行使直接民權，實踐直接民主之補充功能"],["政府統治正當性與限制","為保障人民基本權利免受國家公權力恣意侵害，憲法必須嚴格限縮政府權力邊界（有限政府）","人民有監督政府施政之言論自由、集會遊行自由與請願訴願訴訟權，維護憲政民主秩序"]]);
add('civics-11', "憲法最高性、權力分立制衡機制與五院職權運作", [["憲法位階最高性","憲法為國家根本大法，法律不得牴觸憲法，命令不得牴觸憲法與法律；牴觸者無效","憲法法庭大法官組成審理政黨違憲解散、總統副總統彈劾及法規範與裁判憲法審查案件"],["水平權力分立與制衡","防止權力集中造成專制獨裁，將國家統治權力分割為立法、行政、司法、考試、監察五院互相牽制","行政院向立法院負責提出施政報告；立法院行使法律案預算案審查權及質詢權，形成相互制約機制"],["立法院核心監督職權","制定修正法律、審查通過中央政府總預算案、對行政院長提出不信任案（倒閣權）","對總統提名的司法院大法官、監察委員、考試委員行使人事同意權；提出總統副總統罷免案及彈劾聲請"],["司法獨立與審判超然","《憲法》第八十條規定法官須超出黨派以外，依據法律獨立審判，不受任何外在干涉","司法機關（各級法院）負責民事、刑事與行政訴訟裁判，平息社會紛爭並捍衛人民受憲法保障之權利"]]);
add('visual-1', "視覺藝術造形要素：點線面、色彩明度彩度與質感肌理", [["造形三元素（點線面）","點是視覺焦點與位置起點；線具有方向、律動與張力情緒；面構成形狀與封閉空間輪廓","幾何形（理性規則冷靜）；有機形（自然流暢柔軟有生命力）"],["色彩三屬性","色相（色彩的相貌名稱如紅黃藍）；明度（色彩的明暗深淺程度）；彩度（色彩的純度鮮豔飽和度）","加白提高明度但降低彩度；互補色（色相環相差 180°）並置產生強烈視覺對比"],["質感與肌理表現","觸覺肌理（物體表面真實物理粗糙平滑觸感）；視覺肌理（透過繪畫技法模擬出的表面紋理錯覺）","厚塗法 (Impasto) 利用油彩顏料堆疊立體厚度；水彩渲染展現透明流動質感"],["形式原理綜合引導","運用對比、調和、比例、律動等法則組織造形要素，營造畫面和諧平衡或視覺震撼效果","名畫賞析中先拆解其點線面結構與用色策略，再深入解讀作品背後隱含的情感意象"]]);
add('visual-2', "藝術構圖法則：平衡、對稱、黃金比例與視覺焦點營造", [["對稱與非對稱平衡","對稱平衡（莊嚴、穩定、莊重大氣但易顯單調刻板）；非對稱平衡（透過不同量體位置營造動態心理平衡）","天平兩端等重等形為對稱；大面積淺色與小面積鮮豔深色並置可達成非對稱動態平衡"],["黃金比例與三分法則","黃金分割比約 1:1.618；攝影與繪畫常用九宮格「三分法則」，將主體置於格線交點","避免將地平線或核心主體死板放置於正中央，利用三分線導引視線使畫面更富生動張力"],["透視法與空間深度","焦點透視（單點透視、兩點透視，近大遠小、平行線消失於地平線消失點）；空氣透視法（近景鮮明對比強，遠景偏藍灰模糊）","文藝復興達文西《最後的晚餐》運用精確單點透視，將所有透視消失線匯聚於耶穌頭部焦點"],["引導線與節奏韻律","利用道路、河流、光影或人物視線走向作為引導線，將觀者目光牽引至核心視覺中心","重複出現的形狀、色彩或線條產生音樂般的視覺節奏與律動感"]]);
add('visual-3', "當代視覺文化詮釋、公共藝術介入與批判性審美", [["視覺文化多重脈絡","藝術作品不僅是個人審美創作，更深刻反映創作當代的社會階級、性別政治、歷史事件與哲學思潮","審美時需探究作品產製之時代背景、委託贊助者意圖與觀看者的詮釋脈絡"],["公共藝術與場域精神","公共藝術強調「公共性、藝術性、場域特定性 (Site-specific)」三者結合","非僅在廣場擺放雕塑，而是與在地居民集體記憶、歷史地景與都市空間紋理產生深層對話與互動參與"],["當代新媒體與裝置藝術","打破架上繪畫框架，跨界結合科技影像、聲音、互動裝置、現成物 (Readymade) 與行為表演","杜象《噴泉》顛覆傳統藝術定義；當代藝術更注重觀念探索、社會批判與觀眾沈浸式體驗"],["視覺識讀與消費符號批判","批判性反思流行廣告、社群媒體濾鏡與商業符號背後的消費主義操控與刻板審美焦慮","培養自主審美判斷力，不盲從商業行銷話術，以開放包容心胸接納多元當代藝術實驗"]]);
add('music-1', "音樂核心要素辨識：音高、節奏節拍、調性與織度分析", [["音高與音階組織","音高由發聲頻率決定；十二平均律將八度等分為 12 個半音；自然大調（全全半全全全半）；自然小調（全半全全半全全）","大調明朗宏亮輝煌；小調暗淡憂傷柔和；五聲音階（宮商角徵羽）具東方民族色彩"],["節奏拍號與速度","節拍（每小節拍數，單拍子 2/4、3/4、4/4；複拍子 6/8）；切分音打破正拍強弱規律產生律動推進感","速度術語（Largo 慢板、Andante 行板、Moderato 中板、Allegro 快板、Presto 急板）"],["調性與和聲色彩","調性音樂圍繞主音 (Tonic) 建立穩定中心；三和弦（主和弦 I、下屬和弦 IV、屬和弦 V 建立和聲終止式）","協和音程（同度、八度、純五度、純四度、大三度穩定和諧）；不協和音程（二度、七度、三全音緊張具解決動力）"],["音樂織度四種類型","單音織度（單一旋律線無伴奏）；主調織度（單一主旋律搭配和聲伴奏，最常見）","複調織度（多條獨立旋律線交織對位，如巴哈賦格）；複節奏織度（多種不同節奏型同步交疊）"]]);
add('music-2', "西方音樂風格演進：巴洛克、古典、浪漫到現代主義特徵", [["巴洛克時期（約 1600-1750）","數字低音、複調對位法極致發展、階梯式強弱對比、裝飾音華麗繁複","巴哈（音樂之父，平均律、賦格藝術）；韓德爾（神劇《彌賽亞》）；韋瓦第（協奏曲《四季》）"],["古典樂派（約 1750-1820）","崇尚理性、形式對稱均衡、結構嚴謹清晰，主調音樂確立，奏鳴曲式 (Sonata form) 發展成熟","海頓（交響樂之父）；莫札特（旋律純淨優雅天籟）；貝多芬（樂聖，承先啟後開創浪漫主義先聲）"],["浪漫樂派（約 1820-1900）","強調主觀情感強烈宣洩、個人內心幻想、標題音樂盛行、和聲色彩大膽擴張、民族主義樂派興起","舒伯特（藝術歌曲之王）；蕭邦（鋼琴詩人）；李斯特（交響詩首創）；柴可夫斯基；國民樂派德弗札克"],["現代二十世紀音樂","打破大小調功能和聲傳統，探索無調性 (Atonality)、十二音列技法、印象主義全音階、機遇音樂與電子合成","德布西（印象派光影色彩）；史特拉汶斯基《春之祭》（原始粗獷複合節奏震撼樂壇）"]]);
add('music-3', "臺灣多元傳統音樂體系：南管北管、原住民複音歌謠與跨界創作", [["南管音樂典雅特徵","發源泉州古老樂種，音樂風格清幽典雅徐緩，以拍板、琵琶、三弦、洞簫、二絃等「上四管」為核心","工尺譜記譜法；為文人室內雅集樂曲，被聯合國教科文組織列為非物質文化遺產"],["北管音樂熱烈奔放","流傳於臺灣農村廟會迎神賽會，風格高亢激昂熱鬧喧騰，以嗩吶、通鼓、響盞、大鑼等打擊吹管為主力","分為西皮（新路，主奏樂器吊規仔）與福祿（舊路，主奏樂器殼仔絃）兩大派別，深具民間草根生命力"],["原住民族音樂特色","布農族「八部合音」(Pasibutbut) 以無半音複音和聲祈求小米豐收驚豔國際樂壇","阿美族複音唱答歌謠律動強烈；排灣族與魯凱族雙管鼻笛哀怨悠揚，傳遞貴族生命故事與深層情感"],["傳統音樂當代跨界轉型","傳統傳統器樂與現代管弦樂團、搖滾爵士、當代流行音樂跨界碰撞融合創作","傳統戲曲唱腔融入當代音樂劇，賦予本土傳統音樂全新生命力，展現臺灣當代文化混血包容實力"]]);
add('performing-1', "表演藝術身體肢體開發、聲音表情口條與空間走位調度", [["身體覺察與放鬆機制","透過專注呼吸與脊椎延展進行身心暖身，釋放肩頸肌肉緊繃，建立身體重心穩定感與空間敏銳度","亞歷山大技巧與拉邦動作分析（重力、時間、空間、流動四要素），拓展肢體表現幅度"],["聲音共鳴與咬字發音","腹式呼吸橫膈膜支撐，運用胸腔、口腔、鼻腔與頭腔共鳴發聲，提升音量穿透力與音質厚度","聲母韻母清楚歸音，透過語調起伏、重音位置與停頓留白精準傳遞角色潛台詞與內在潛在情緒"],["舞台空間九宮格走位","舞台劃分：上舞台（遠離觀眾側）、中舞台、下舞台（靠近觀眾側）及左、中、右側","舞台下中位置通常最具視覺權威張力；人物走位須符合動機邏輯，避免無意義背對觀眾或遮蔽同台演員"],["肢體能量傳遞與默契","演員之間相互拋接球般的注意力專注傾聽與動作反饋，建立有機生動的舞台當下臨場反應","透過即興練習培養與對手演員之呼吸共振，建立真實不造作的舞台有機互動關係"]]);
add('performing-2', "戲劇衝突情境鋪陳、角色動機建立與劇本分鏡創作", [["戲劇三幕結構模型","第一幕鋪陳（介紹主要角色、背景與引爆事件）；第二幕對抗（衝突升高、危機接踵而至、達到全劇最高潮）","第三幕結局（高潮後的釋放解決、真相大白或命運終局沉澱）"],["角色動機與內外阻礙","角色核心「想要什麼（內在超目標 Super-objective）」；「面臨何種困難阻礙（外部環境或內心天人交戰）」","有強烈動機與阻礙才會產生戲劇張力；避免平面單一臉譜化扁平人物，塑造多面向複雜人性"],["戲劇衝突三大維度","人與自身的心理道德內在衝突；人與人的利益理念人際衝突；人與社會體制、命運或自然環境之巨大衝突","衝突是戲劇前進的燃料；透過衝突迫使角色在兩難絕境中做出關鍵道德抉擇"],["劇本格式與舞台指示","包含場景標題（內/外景、地點、時間）、人物對話（台詞）、以及括號內之「舞台指示（動作、情緒、走位、音效光影提示）」","台詞講究精煉生活化並蘊含潛台詞，切忌直白說教或冗長資訊交代"]]);
add('performing-3', "劇場幕後製作要素整合、技術協調與排練演職規範", [["劇場製作核心職群","導演（統籌藝術觀點詮釋調度）；編劇（劇本文本創作）；舞台監督（掌控排練演出技術執行與最高安全總指揮）","製作人（行政資源預算籌措行銷）；各部門設計師（舞台、燈光、音效、服裝梳化）各司其職"],["舞台形式多樣性","鏡框式舞台（觀眾單面觀看，具台口框與第四面牆神秘感）；三面式舞台（觀眾環繞三側，演員與觀眾親密互動）","黑盒子劇場（靈活彈性調整觀眾席與表演區配置，適合前衛實驗性創作）"],["燈光音效之戲劇氛圍","燈光三點照明（主光、輔光、輪廓逆光）；色溫色光營造情緒氛圍；聚光燈 (Spotlight) 鎖定視覺焦點","音效配樂烘托時代情境、渲染懸疑恐懼或激越氛圍，轉場音樂維持觀戲節奏連貫"],["排練紀律與劇場安全規範","嚴格遵守排練時間守時守紀；道具服裝物歸原位；舞台懸吊系統與高空換景作業恪守安全重載標準","技術著裝排練 (Tech run) 與彩排 (Dress rehearsal) 徹底測試燈光音響機關銜接，落實應急疏散安全演練"]]);
add('computing-1', "運算思維四大基石：問題拆解、模式識別、抽象化與演算法", [["問題拆解 (Decomposition)","將龐大複雜難解的整體問題，有條理地分解為若干個較小、獨立且易於處理的子問題","開發外送系統：拆解為地圖定位模組、菜單結帳模組、外送員派單系統、評分回饋模組分頭擊破"],["模式識別 (Pattern Recognition)","觀察不同子問題或過往經驗之間的相似規律、共同趨勢與重複特徵","發現學生成績排名、圖書館圖書編目、購物網站價格排序，皆可共通套用「數值排序演算法」解決"],["抽象化 (Abstraction)","過濾抽離掉不重要的枝節細節，僅聚焦保留與問題核心關聯最密切的關鍵屬性與規則","捷運路線圖省略真實曲折地理彎道與比例尺，僅抽象保留各站轉乘站點拓撲連通關係"],["演算法設計 (Algorithm Design)","擬定一套有限、明確、具體且按部就班可執行的邏輯步驟指令，確保能產出正確解答","食譜步驟、搜尋引擎排序規則；具備明確輸入、明確輸出、有限性、確定性與可行性"]]);
add('computing-2', "結構化程式設計控制流程：循序、選擇判斷、迴圈迭代與函式模組化", [["循序結構 (Sequential)","程式碼由上至下依序逐行執行，前一行未完成前不跳步執行下一行","變數必須先宣告賦值後，才能在後續運算式中讀取使用，否則引發未定義變數錯誤"],["選擇判斷結構 (Selection)","依條件布林運算式之真假 (True/False) 決定程式執行分支路徑 (if / elif / else)","若成績 ≥ 60 輸出「及格」，否則輸出「補考」；巢狀判斷需注意條件邊界互斥性與縮排階層"],["迴圈迭代結構 (Iteration)","計數型迴圈 (for) 針對已知次數或集合項目迭代；條件型迴圈 (while) 當條件滿足時持續重複執行","計算 1 到 100 累加和用 for 迴圈；提款機密碼驗證在未超過 3 次且密碼錯誤時用 while 迴圈反覆輸入"],["函式模組化 (Function)","將具有特定功能的程式碼區塊封裝成可重複呼叫的獨立函式，傳入參數並回傳 (return) 運算結果","大幅減少重複程式碼、提高維護可讀性、實現資訊隱藏與軟體工程元件重用價值"]]);
add('computing-3', "資訊倫理規範、網路個人隱私防護、智慧財產權與數位公民素養", [["個人隱私與數位足跡","個人敏感資料（身分證字號、生物辨識、地理位置、帳號密碼）切勿隨意在公開網路平台洩漏","網路瀏覽行為會留下 Cookie 與搜尋數位足跡；公共 Wi-Fi 網路應避免登入網銀或進行未加密金融交易"],["智慧財產權與創用 CC","未經授權不得下載、拷貝、重製、販售或散布他人享有著作權之音樂、影視、軟體或文章","創用 CC (Creative Commons) 四大授權標示：姓名標示 (BY)、非商業性 (NC)、禁止改作 (ND)、相同方式分享 (SA)"],["資安防護與社交工程攻擊","設定強度高且獨立不共用之長密碼，啟用雙重驗證 (2FA)；防範網路釣魚郵件與惡意偽造連結","社交工程常利用人性恐懼或好奇心誘騙點擊假中獎通知或假檢警簡訊，絕不依指示轉帳或提供驗證碼"],["數位公民素養與反網路霸凌","在虛擬網路社群發言同樣承擔法律責任，禁止公然侮辱、誹謗、散布性私密影像或發動人肉搜索","遇網路霸凌事件截圖存證、向平台檢舉檢舉並向家長老師或 iWIN 網路防護機構尋求專業諮詢協助"]]);
add('technology-1', "工程設計流程五大階段：定義問題、發想構想、原型製作、測試評估與迭代優化", [["定義問題與確認需求","深入調查使用者痛點，明確列出設計限制條件（材料成本、尺寸重量、加工安全、環保規範）","非憑空想像，例如設計校園雨傘架：需解決積水滑倒、防盜收納與空間佔用等具體規格要求"],["發想構想與草圖繪製","透過心智圖、腦力激盪發想多元解決方案；繪製三視圖（正視圖、俯視圖、側視圖）與等角立體圖表達構造","草圖需標註關鍵加工尺寸、公差配合與選用材質，供後續實體加工依循"],["原型製作 (Prototyping)","善用手工具（手鋸、挫刀、角尺）與數位製造工具（3D 列印機、雷射切割機）製作功能原型 (Prototype)","先製作低成本紙板打樣驗證尺寸構造可行性，再進行硬質木材、壓克力或金屬機件精密切割加工"],["測試評估與迭代優化","訂定客觀量化測試指標（承重極限、抗摔強度、開闔次數），記錄故障數據並回饋修改設計","工程設計是一個持續循環改善 (Iteration) 的過程，從失敗測試中發掘問題進行下一輪演進"]]);
add('technology-2', "機構原理與動力傳遞系統：齒輪、皮帶輪、鏈條、凸輪與連桿機構", [["齒輪傳動機構","靠輪齒嚙合傳遞動力，傳動比固定無滑動；齒數比與轉速成反比 (N₁/N₂ = T₂/T₁)","主動輪帶動從動輪時，兩輪轉向相反；若加入惰輪（中間齒輪），轉速比不變但使從動輪轉向同向"],["皮帶輪與鏈條傳動","皮帶輪靠摩擦力傳動，距離較遠且過載時會打滑具保護馬達功能；鏈條靠鏈輪嚙合無打滑但需潤滑防噪","自行車採用鏈條傳動；洗衣機內膽馬達採用皮帶輪傳動"],["凸輪機構運動轉換","凸輪旋轉帶動從動件產生規律的往復直線運動或擺動，能將連續旋轉轉化為間歇非等速運動","汽車引擎汽門開啟與關閉機構；凸輪輪廓曲線決定從動件的位移規律與停歇時間"],["四連桿機構應用","由四個剛性桿件鉸接而成：機架、曲柄（可 360° 全迴轉）、搖桿（僅能左右擺動）與連桿","雨刷擺動機構將馬達連續旋轉轉化為雨刷左右往復扇形擺動；折疊傘骨架與挖土機怪手懸臂"]]);
add('technology-3', "新興科技趨勢、綠色能源整合應用與智慧感測自動控制系統", [["微控制器與感測器","微控制器 (如 Arduino, micro:bit) 接收感測訊號，依程式邏輯輸出控制訊號驅動致動器","光敏電阻感測光線強度、超音波感測障礙物距離、溫濕度感測器；驅動伺服馬達、蜂鳴器或繼電器"],["自動控制開迴路與閉迴路","開迴路無回饋訊號（如定時洗衣機時間到即停）；閉迴路具回饋修正機制，將輸出與目標比對持續修正","冷氣恆溫控制：溫度感測器持續測量室溫與設定值比較，自動調節壓縮機運轉頻率（負回饋控制）"],["綠色綠能科技整合","太陽能光電板（光電效應直流電）、風力發電、生質能；搭配蓄電池儲能系統與智慧電網調度","生活科技專題中利用太陽能車實驗，探討光照角度與負載電壓輸出效率之工程優化"],["永續循環材料科技","推動全生命週期循環經濟概念：低耗能無毒環保材料、生質可降解塑料與模組化易拆解維修設計","評估產品從原料開採、製造包裝、運送使用到廢棄回收之碳足跡，落實環境永續共生理念"]]);
add('health-1', "全人健康全方位指標、慢性生活型態疾病預防與自主健康管理", [["全人健康四大維度","生理健康（無疾病活動自如）、心理健康（正向情緒接納自我）、社會健康（人際和諧良好適應）、靈性健康（生命意義與價值追尋）","健康不僅僅是沒有生病衰弱，而是身心靈與社會處於完全和諧健全的理想幸福狀態"],["代謝症候群五大危險指標","腹部肥胖（男性腰圍 ≥ 90cm、女性 ≥ 80cm）、血壓偏高 (≥ 130/85 mmHg)、空腹血糖偏高 (≥ 100 mg/dL)","三酸甘油酯偏高 (≥ 150 mg/dL)、高密度脂蛋白膽固醇偏低（男 < 40、女 < 50 mg/dL）；符合 3 項即為代謝症候群"],["慢性疾病生活型態預防","高血壓、心血管疾病、第 2 型糖尿病與癌症等非傳染性慢性病，與久坐少動、精緻高糖油炸飲食密切相關","戒菸節酒、少油少鹽高纖飲食、規律有氧運動與充足睡眠，可有效降低 80% 慢性病罹患風險"],["個人自主健康檢測記錄","定期量測血壓心率、記錄 BMI 與身體組成、定期接受成人健康檢查與癌症篩檢","主動關照身體發出的疲勞疼痛警訊，不盲信網路偏方，具備自我健康照護賦能素養"]]);
add('health-2', "心理情緒覺察、多元壓力調適因應策略與身心求助資源網絡", [["情緒覺察與接納認知","情緒無好壞對錯之分，每一種情緒（憤怒、焦慮、悲傷、嫉妒）都是大腦傳遞內在需求的信號","命名情緒以馴服情緒 (Name it to tame it)；允許自己有脆弱悲傷時刻，以不批判態度溫柔覺察當下"],["壓力生理與心理反應","面臨壓力事件大腦杏仁核發動警報，交感神經興奮釋放腎上腺素與皮質醇，引發心跳加速呼吸急促","短暫急性壓力有助於激發潛能集中注意力；長期慢性壓力會壓制免疫系統導致失眠憂鬱與身心耗竭"],["建設性壓力調適策略","運動宣洩釋放腦內啡與多巴胺；正念腹式呼吸冥想平衡自律神經；從事藝術塗鴉創作或親近自然綠色療癒","認知重構 (Cognitive reframing)：將「災難化思考」轉化為「挑戰性思維」，專注於自己可控制之部分"],["專業心理求助管道連線","當負面情緒持續超過兩週且嚴重影響學業生活功能時，應主動向信任師長、輔導室輔導教師求助","善用校外專業求助專線：衛福部安心專線 1925（依舊愛我）、生命線 1995、張老師 1980 及身心科專業醫療評估"]]);
add('health-3', "物質濫用危害防制、成癮神經生物機制與人際堅定拒絕技能", [["成癮神經生物學機制","成癮物質（毒品、酒精、尼古丁）強烈刺激大腦中腦邊緣「多巴胺獎賞回饋迴路」暴增","大腦產生耐受性 (Tolerance)，需更大劑量才能達到相同快感；停用引發強烈痛苦的戒斷症狀 (Withdrawal)"],["常見成癮物質危害辨別","菸草與電子煙（尼古丁成癮強烈、重金屬與甲醛致癌肺損害）；酒精（抑制中樞神經損害大腦肝硬化）","新興毒品（常偽裝成毒咖啡包、彩虹煙、跳跳糖、果凍），混雜多種未知名化學藥物極易致死猝死"],["毒品防制法規與陷阱","毒品依成癮性危害性分四級，持有販賣運輸皆負重大刑責；絕不可替陌生人攜帶行李包裹進出海關","出入夜店派對等娛樂場所，飲料絕不可離開視線範圍，不接受來路不明的拆封食品飲料招待"],["堅定拒絕五大技巧","直接堅持拒絕（勇敢說不堅定眼神）；藉故離開現場（尿遁電話逃離）；轉移話題焦點；自我解嘲幽默帶過；反客為主說服對方","建立健康自我界線，重視自身生命安全價值，切勿為了迎合同儕或追求刺激誤入毒品萬劫不復深淵"]]);
add('pe-1', "體適能五大要素科學評估、運動處方 (FITT) 與自主訓練計畫", [["健康體適能五大要素","心肺耐力（登階測驗、心肺長跑）；肌力與肌耐力（仰臥起坐、屈臂懸垂）；柔軟度（坐姿體前彎）；身體組成（BMI、體脂率）","五大要素均衡發展是維持良好生活品質、預防運動傷害與提升學習專注力之基石"],["FITT 運動處方原則","頻率 (Frequency，每週 3-5 次)；強度 (Intensity，最大心率 60-80% 或自覺量表 RPE)","時間 (Time，每次 30-60 分鐘)；型態 (Type，有氧耐力跑、自重肌力抗阻、靜態伸展瑜珈)"],["目標心率計算公式","最大心率估算 HRmax = 220 - 年齡；目標心率區間 = HRmax × 60% ~ 85%","運動手錶監控運動心率維持於有效燃脂與心肺刺激區間，避免過度訓練引發心血管超負荷疲勞"],["自主體能計畫週期規劃","分階段循序漸進：基礎適應期 → 肌力強化期 → 專項體能高峰期；訓練必須搭配充分營養與睡眠修復","每 4-6 週重新評估體適能各項數據，動態微調訓練動作與負荷強度，培養終身自主規律運動習慣"]]);
add('pe-2', "球類團隊運動攻防戰術思維、團隊合作默契與崇高運動道德", [["空間利用與跑位拉扯","進攻時利用傳切配合 (Give and go)、擋拆掩護 (Pick and roll) 拉開對手防守陣型創造空檔投射機會","無球跑動 (Off-ball movement) 是頂級進攻的核心，透過空切、反跑與假動作擺脫防守盯人"],["防守戰術體系辨析","人盯人防守（每人嚴格負責盯防固定對手，強調個人防守步法滑步與對抗責任）","區域聯防（按場地責任區站位，壓縮內線禁區空間保護籃板，但外圍三分線空檔較大易被破解）"],["團隊溝通與默契培養","場上即時清晰呼應口令（防守幫忙、單擋注意、換防、籃板回防），彌補隊友盲區與體能漏洞","勝不驕敗不餒，彼此鼓勵包容失誤，放下個人數據英雄主義，以團隊勝利為最高戰略目標"],["運動家精神與規則尊重","嚴格恪守比賽規則，服從裁判公正判決，絕不刻意進行具危險傷害性之惡意犯規動作","以球會友尊重對手球員與觀眾，在激烈競技中淬鍊堅毅挫折容忍力與高尚道德品格"]]);
add('pe-3', "運動傷害預防、急性處理 PRICE 原則與環境風險評估", [["運動前暖身與運動後收操","動態暖身（關節環繞、開合跳、高抬腿跑步提振心率與肌肉溫度，降低拉傷機率）","靜態伸展收操（運動後針對緊繃肌群緩慢拉伸維持 15-30 秒，促使乳酸代謝減緩延遲性肌肉酸痛 DOMS）"],["急性軟組織傷害 PRICE 原則","P (Protect 保護患部)；R (Rest 立即停止運動休息)；I (Ice 冰敷每次 15-20 分鐘減緩腫脹發炎)","C (Compression 彈性繃帶適度加壓包紮止血)；E (Elevation 抬高患部高於心臟促進靜脈血液回流)"],["常見運動傷害類型","肌肉拉傷（肌纖維過度伸展撕裂）；韌帶扭傷（關節過度扭曲韌帶受損，如腳踝翻船）","抽筋（肌肉不自主強烈痙攣，與電解質流失脫水疲勞有關，應反向緩慢溫和拉伸放鬆）"],["戶外環境風險防範","高溫潮濕環境嚴防熱傷害（熱痙攣、熱衰竭、熱中暑）；及時補充水分與電解質，穿著透氣排汗衣物","天候驟變（雷擊、暴雨、路滑）應立即終止戶外運動，確認場地平整無異物障礙，確保安全第一"]]);
add('home-1', "均衡飲食指南、營養素功能、食品標章識讀與個人健康餐盤規劃", [["六大類食物均衡攝取","全穀雜糧類（碳水化合物主要能量來源）；豆魚蛋肉類（優質蛋白質組織建構修復）；蔬菜類與水果類（維生素、礦物質與膳食纖維）","乳品類（鈣質強化骨骼牙齒）；油脂與堅果種子類（必需脂肪酸與脂溶性維生素吸收）"],["「我的餐盤」口訣比例","每天早晚一杯奶、每餐水果拳頭大、菜比水果多一點、飯跟蔬菜一樣多、豆魚蛋肉一掌心、堅果種子一茶匙","餐盤中深綠色與深黃紅色蔬菜應占 1/3 以上，全穀雜糧盡量選擇未精製糙米燕麥地瓜"],["食品營養標籤識讀","檢視「每份」熱量與營養素含量，換算「本包裝含幾份」計算總攝取熱量","成分表按「含量多到少」依序排列；緊盯鈉含量（每日建議上限 2400 mg）與添加精緻糖含量比例"],["食品安全三級品管標章","認明標章保障食安：CAS 臺灣優良農產品標章、TAP 產銷履歷農產品標章、有機農產品標章","生熟食分開處理避免交叉感染；注意保存期限與冷藏 (0-7°C)、冷凍 (-18°C) 正確溫控防腐"]]);
add('home-2', "家庭資源整合管理、個人時間理財規劃與家庭良性溝通策略", [["家庭資源兩大類別","人力資源（知識技能、時間體力、家庭成員情感與創造力）；非人力資源（金錢財富、房產汽車、公共社區設施）","資源具備有限性與替代性，妥善盤點調配可大幅提升家庭生活福祉與抗風險韌性"],["時間管理四象限法","緊急且重要（危機事故立即處理）；重要但不緊急（讀書計畫、規律運動、生涯規劃、情感經營）","不重要但緊急（多數打擾電話即時訊息）；不重要且不緊急（沉迷滑手機廢物追劇；應嚴格減少避免）"],["青少年理性理財思維","區分「需要 (Need)」與「想要 (Want)」；建立預算規劃與零用錢記帳習慣，落實「收入 - 儲蓄 = 支出」","避免衝動消費與同儕攀比，了解複利累積威力與消費信貸潛在風險，奠定長期財務獨立基石"],["家庭良性溝通與界線","溝通三要素：說清楚、聽明白、核對理解；避免使用「你總是...」、「你每次都...」等攻擊標籤詞","家庭分工透過定期家庭會議共同協商，互相承擔家務責任，營造平等尊重溫馨家庭支持氛圍"]]);
add('home-3', "織物纖維特性、衣物洗滌保養標籤識讀與綠色永續消費實踐", [["常見織物纖維分類","天然纖維（植物纖維如棉麻吸濕透氣易皺；動物纖維如羊毛蠶絲保暖親膚但易縮水遇熱變性）","人造化學纖維（合成纖維如聚酯纖維、尼龍耐磨抗皺快乾但易起毛球靜電與悶熱）"],["國際洗滌保養標籤識讀","水洗槽符號（水洗溫度、手洗標示）；三角形（漂白限制，打叉嚴禁氯漂）；正方形內圓形（烘乾限制）","熨斗符號（熨燙溫度限制點數）；圓形（乾洗限制標示；不可水洗高檔毛料送專業乾洗）"],["衣物污漬化學處理","油性污漬用洗碗精或界面活性劑局部乳化分解；蛋白質血漬切忌用熱水（會使蛋白質凝固變性），須用冷水清洗","深淺色衣物分開洗滌防染色；細緻衣物與拉鍊衣物裝入洗衣袋保護，延長衣物使用壽命"],["綠色永續慢時尚實踐","拒絕「快時尚」造成的巨大水資源浪費、微塑膠纖維海洋污染與成衣堆積掩埋災難","實踐 3R 原則：減少購買 (Reduce)、二手交換重用 (Reuse)、衣物修補升級改造 (Recycle/Upcycle)"]]);
add('scout-1', "戶外露營安全規劃、營地營帳搭設防護與無痕山林 (LNT) 七大原則", [["安全營地選址準則","地勢平坦乾燥微傾斜排水良好、避開落石懸崖下方、遠離枯樹死枝、嚴禁紮營於乾涸河道與河床沙洲防暴雨山洪","迎風背風考量：避開強風鞍部迎風隘口，營門避開迎風面，水源維持安全取水距離但不可污染水源"],["帳篷搭設防風防雨要領","清除地面尖銳碎石松果，鋪設外地布阻隔地下濕氣；營柱扣合穩固，營釘與地面成 45-60° 斜角牢固打入","外帳必須徹底拉緊拉繩外擴，確保內外帳不貼合，避免反潮雨水滲入內帳，挖設周邊排水小溝引流"],["無痕山林 (LNT) 核心準則","1.事前充分規劃與準備；2.在可承受地點行走與紮營；3.妥善處理廢棄物垃圾全帶下山；4.保持環境原貌不破壞","5.減低用火對環境的衝擊；6.尊重野生動植物不餵食打擾；7.考量其他使用者禮讓山徑保持寧靜"],["戶外安全緊急應變計劃","攜帶離線登山地圖與衛星通訊設備，落實留守人報備制度","天候惡化果斷終止行程下撤；遇山難恪守 STOP 原則原地待援"]]);
add('scout-2', "童軍實用繩結技術（平結、雙半結、稱人結）與先鋒工程搭設應用", [["平結 (Reef Knot)","用於連接兩條「粗細相同」的繩索，結形扁平易解，常用於急救三角巾包紮固定","兩端繩頭「左壓右、右壓左」；切記粗細不同的繩索不可用平結連接，極易滑脫鬆散"],["接繩結與雙半結","接繩結（專門用於連接兩條「粗細不同」之繩索）；雙半結（用於將繩子固定在柱子或樹幹上，越拉越緊易打好解）","營繩調整鬆緊常搭配雙半結或營繩結使用，確保帳篷外帳迎風拉力平衡"],["稱人結 (Bowline Knot)","「繩結之王」，能在繩端打出大小固定且永不收緊滑脫的強固安全環圈","用於野外攀岩下降、人體吊掛急救吊帶、固定船隻纜繩；受巨大拉力後依然能輕鬆拆解"],["先鋒工程綁紮法 (Lashing)","方綁（兩垂直竹木交叉固定）；十字綁（傾斜交叉桿件固定）；剪立剪綁（製作三腳架與剪刀架結構）","工程架設前檢查木料韌性，以麻繩確實拉緊咬合咬繩，搭建營門、瞭望台與餐桌，展現團隊協作工程力"]]);
add('scout-3', "野外求生定向導航、求救信號傳遞與失溫熱傷害緊急處置", [["指北針與地圖定向","指北針磁針紅端恆指磁北；將地圖北向與指北針調整一致完成定向 (Map orientation)","利用等高線地標地形比對現地特徵，找出自身前進方位角；夜間利用北極星（北斗七星或仙后座）指引正北"],["求救信號傳遞規範","國際山難通用求救信號：一分鐘發出 6 次信號（鳴笛、哨音、手電筒閃光、反光鏡反射），間隔一分鐘重複","地面擺放大型「SOS」或「X」型亮色求救標誌導引搜救直升機；三處狼煙在空中呈等距三角排列"],["迷途處置原則 (STOP)","S (Stop 立即停止前進保持冷靜)；T (Think 思考冷靜評估現狀)；O (Observe 觀察周遭環境水源與避難地形)；P (Plan 擬定避難求生計畫)","迷路時「切忌盲目往溪谷下切」（溪谷斷崖瀑布密布阻隔無法攀爬且易失溫），應回到稜線或留在原地待援"],["失溫防制處置機制","失溫成因三要素：低溫、強風（風寒效應加速奪走熱量）、潮濕；出現顫抖遲鈍說話不清即為失溫徵兆","立即脫去濕冷衣物換穿乾衣，躲入避風帳或太空保溫毯，飲用溫熱含糖飲料，嚴禁直接火烤或劇烈摩擦肢體"]]);
add('guidance-1', "個人特質多元探索、生涯興趣性向覺察與自我價值觀澄清", [["生涯金三角架構","個人特質（知己：興趣、性向、人格特質、價值觀）；教育與職業世界（知彼：學校類科、職場生態、產業趨勢）；環境因素（家庭期望、社會經濟環境）","生涯抉擇是三者動態平衡尋求交集的理性思辨與價值探索過程"],["何倫生涯代碼 (RIASEC)","實用型 (R，動手操作機具)；研究型 (I，邏輯分析探究真理)；藝術型 (A，創意美感自我表現)","社會型 (S，熱心助人關懷溝通)；企業型 (E，領導說服承擔風險)；常規型 (C，細心條理數據文書)"],["性向與興趣差異辨析","興趣是指「喜歡做的事（做這件事感到熱情愉悅）」；性向是指「學習這件事的潛能與天賦能力」","興趣與性向高度重疊固然理想；若興趣與性向有落差，可透過刻意練習彌補能力，或將興趣發展為休閒調劑"],["生涯價值觀排序澄清","金錢財富、社會地位、自主自由、助人奉獻、工作穩定、生活平衡、挑戰冒險","生涯價值觀決定人生的優先順序；透過價值觀拍賣活動探索內心真正不可妥協的核心追求"]]);
add('guidance-2', "高效學習策略診斷、元認知監控調控與自主學習計畫擬定", [["元認知（後設認知）循環","對自己認知過程的認知：計畫 (Plan) → 監控 (Monitor) → 評估與反思調整 (Evaluate/Reflect)","做題目時不僅關注答案對錯，更主動反思：「我用了什麼解題策略？這條公式適用的前提條件是什麼？」"],["分散學習與提取練習","艾賓浩斯遺忘曲線：拒絕考前死記硬背通宵抱佛腳，採取「間隔重複 (Spaced repetition)」複習","「主動提取練習 (Active recall)」成效遠勝於被動反覆畫線閱讀：闔上講義自我解釋概念並完成白紙回憶"],["費曼技巧學習法則","1.選擇目標概念；2.嘗試用最白話的語言教會一個小學生或外行；3.卡住卡頓處翻查教材查漏補缺；4.簡化類比精煉表達","能用通俗易懂的語言講清楚道理，才代表真正內化掌握核心知識本質"],["SMART 自主學習目標","目標必須符合：S (具體)、M (可量化評估)、A (可達成)、R (相關性高)、T (有明確完成時限)","例如：「每週二與週四晚間各花 30 分鐘，完成 2 篇英文閱讀與 10 題數學十字交乘練習並訂正」"]]);
add('guidance-3', "國中生涯進路試探、普通高中與技職體系跨軌規劃與抉擇決策", [["普通高中體系特徵","以通識基礎學科為主軸（國英數社自加深加廣），為大學多元專業領域學習深造奠定扎實學術基礎","適合對學術研究、抽象理論思辨具濃厚興趣，生涯定向仍在多元探索階段的學生"],["技術型高中（高職）十五群科","以專門技術實作、技能檢定與專業知識為導向，分為機械群、動力機械群、電機電子群、化工群、設計群、餐旅群等","實作實習課程占比高，產學合作緊密，畢業後可直接報考四技二專統測升學或就業接軌專門技術證照"],["綜合型高中與五專體系","綜合高中高一修習普通課程，高二依性向自由分流學術學程或專門學程；五專（五年制專科）國中畢業直接就讀，扎實培育高階中階實務技術人才","插班大學二技或就業彈性多元，兼具理論基礎與實務即戰力"],["理性生涯決策平衡單","運用「決策平衡單」量化評估各進路選項：自我物質得失、他人物質得失、自我贊同、他人贊同加權計分","破除「唯有讀書高」傳統迷思，行行出狀元，選擇最契合自身天賦特質與熱情的生涯航道"]]);
add('local-1', "本土語文羅馬拼音系統、聲調符號標記與語音音韻辨識", [["臺灣閩南語羅馬字拼音 (臺羅)","聲母（17 個如 p, ph, m, t, th, n, k, kh, g, ng, h, ts, tsh, s, j）與韻母（母音、鼻化韻、入聲韻尾 -p, -t, -k, -h）","辨識聲母送氣 (ph, th, kh, tsh) 與不送氣 (p, t, k, ts) 之清濁對立差異"],["臺羅八個聲調符號標記","第 1 聲（高平調 a）、第 2 聲（高降調 á）、第 3 聲（低平/低降調 à）、第 4 聲（低促入聲 ah/ap/at/ak）","第 5 聲（低升調 â）、第 7 聲（中平調 ā）、第 8 聲（高促入聲 áh/áp/át/ák）；第 6 聲多數腔調與第 2 或第 7 聲合流"],["客家語拼音方案六大腔調","四縣腔、海陸腔（兩大主流）、大埔腔、饒平腔、詔安腔、南四縣腔","海陸腔與四縣腔聲調高低起伏恰呈互補鏡像對應（如四縣陰平為高平調，海陸陰平為低降調）"],["連讀變調規律掌握","本土語詞彙在連續說話時，除詞尾最後一個字維持本調外，前字皆會產生規律的「連讀變調」","變調口訣熟練掌握；若不變調直接唸本調，語音聽感僵硬不自然，甚至引發語意誤解"]]);
add('local-2', "本土語文生活日常情境對話、特色詞彙語法與漢字書寫對照", [["生活常用情境用語","問候禮儀、飲食購物、交通問路、家庭生活等流利口語對話表達","「食飽未？（吃飽了嗎？）」「多謝、勞力（謝謝）」「借借問一下（請問一下）」「代誌（事情）」"],["教育部推薦常用漢字對照","「𠢕 (gâu，優秀厲害)」、「予 (hōo，給或被)」、「共 (kā，把或向)」、「佮 (kah，和或與)」、「莫 (mài，不要)」","掌握標準教育部推薦字，避免隨意使用非標準之諧音借字（如「凍蒜」、「水啦」），建立規範閱讀書寫能力"],["特色語法句型結構","否定詞多樣性：「無 (bô，沒有)」、「袂 (bē，不會/不能)」、「毋 (m̄，不是/不願意)」、「未 (buē，尚未)」各有特定用法","處置句與被動句結構：「伊共碗打破（他把碗打破了）」、「魚仔予貓食去（魚被貓吃掉了）」"],["原住民族語生活詞彙特徵","南島語系構詞法：主賓動詞順序 (VSO)，大量運用詞首綴、詞中綴、詞尾綴變換時態與焦點格位","學習部落問候語、親屬稱謂、自然山川地名意涵，體現人與自然共生共榮哲學"]]);
add('local-3', "本土俗諺俚語哲理、民間民間故事傳奇與傳統民俗節慶文化意涵", [["生活哲理俗諺意涵","「食果子，拜樹頭；食米飯，敬田頭」體現飲水思源感恩自然惜福精神","「一枝草，一點露；天無絕人之路」勉勵逆境奮鬥天生我材必有用之堅韌生命韌性"],["民間傳奇故事導讀","林投姐（揭露社會不公女性悲情復仇）；廖添丁（義賊劫富濟貧反抗殖民統治集體心理投射）","嘉慶君遊臺灣、蛇郎君、白賊七民間智慧趣味寓言，蘊含民眾對正義道德與智慧的嚮往"],["歲時節慶民俗儀式","農曆春節過年（圍爐走春）、元宵節（平溪天燈、鹽水蜂炮）、清明掃墓培墓敬祖","端午節（划龍舟、掛艾草菖蒲辟邪防瘟）、中元普渡（悲憫無主孤魂孤魂野鬼之博愛胸懷）、冬至（搓湯圓象徵圓滿添歲）"],["傳統工藝與民俗表演","傳統掌中木偶戲（布袋戲口白雕刻）、皮影戲、歌仔戲身段唱腔、陣頭跳鼓宋江陣藝術","民俗活動深具社會凝聚、道德教化、心理慰藉與族群歷史認同等多重文化功能"]]);
add('local-4', "本土文學作家作品賞析、現代歌謠創作與母語文化復振倡議", [["日治與戰後本土文學先驅","賴和（臺灣新文學之父，《一桿「稱仔」》批判殖民壓迫）；楊逵（《送報伕》展現普羅大眾抗爭精神）","鍾理和（客家文學硬頸精神《笠山農場》）；黃春明、向陽（臺語現代詩《咬舌詩》聲援本土語言）"],["現代本土音樂歌謠演進","鄧雨賢經典望春風、雨夜花；新臺語歌運動（林強《向前走》打破悲情開創搖滾自信活力）","金曲獎多元語文（客語生祥樂隊、原住民林生祥、舒米恩、阿爆）跨界國際音樂舞台"],["國家語言發展法精神","2019 年公布《國家語言發展法》，明定臺灣各族群固有之自然語言及臺灣手語皆為「國家語言」","保障語言權為基本人權，反對母語歧視，各級學校全面推動本土語言列入部定必選修課程"],["母語復振與日常生活實踐","「講母語，真光榮！」在家庭與同儕日常對話中主動營造母語沉浸式生活環境","善用數位母語字典、Podcast 播客與母語影音創作，讓珍貴的本土語言在青年世代生生不息永續繁衍"]]);

export const teachingTables = tables;
const esc = value => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
export function knowledgePoints(u) {
  return u.concept.split(/。|；/).map(s=>s.trim()).filter(Boolean);
}
export function teachingFor(u) {
  const base = tables[u.id];
  if (base) {
    const pts = knowledgePoints(u);
    const unitSpecificRows = [
      ['本課核心判準', pts[0] ? `${pts[0]}。` : u.concept, `代表例證：${u.example}`],
      ['本課易錯防線', u.pitfall, `遷移檢核：${u.task}`]
    ];
    return {
      title: base.title.includes(u.title) ? base.title : `${u.title} · ${base.title}`,
      rows: [...base.rows, ...unitSpecificRows]
    };
  }
  return {title: `${u.title} · 概念、應用與界線對照`, rows:[
    ...knowledgePoints(u).map((point,i)=>['核心 '+(i+1),point,'試著用下方例題，說明這項概念如何影響判斷。']),
    ['應用情境',u.example,'先辨識已知條件，再對照上列概念。'],
    ['易錯界線',u.pitfall,'提出一個會犯此錯誤的例子，再改正理由。']
  ]};
}
function getRowIcon(label) {
  if (label.includes('核心判準') || label.includes('核心')) return '🎯';
  if (label.includes('易錯') || label.includes('防線') || label.includes('陷阱')) return '🛡️';
  if (label.includes('比') || label.includes('公式') || label.includes('算') || label.includes('數') || label.includes('量')) return '📐';
  if (label.includes('實驗') || label.includes('反應') || label.includes('細胞') || label.includes('器官') || label.includes('波')) return '🔬';
  if (label.includes('法') || label.includes('權') || label.includes('制度') || label.includes('責任') || label.includes('程序')) return '⚖️';
  if (label.includes('史') || label.includes('年代') || label.includes('文明') || label.includes('變革')) return '📜';
  if (label.includes('氣候') || label.includes('地') || label.includes('板塊') || label.includes('洋') || label.includes('環境')) return '🌍';
  if (label.includes('語') || label.includes('句') || label.includes('字') || label.includes('詞') || label.includes('閱讀') || label.includes('篇')) return '✍️';
  return '📌';
}

function getDomainMeta(subject) {
  if (['math'].includes(subject)) return { icon: '📐', label: '數理邏輯' };
  if (['biology', 'physics', 'chemistry', 'earth'].includes(subject)) return { icon: '🔬', label: '自然探究' };
  if (['chinese', 'english', 'local'].includes(subject)) return { icon: '✍️', label: '語文溝通' };
  if (['history', 'geography', 'civics'].includes(subject)) return { icon: '🌍', label: '社會人文' };
  if (['visual', 'music', 'performing'].includes(subject)) return { icon: '🎨', label: '藝術素養' };
  if (['computing', 'technology'].includes(subject)) return { icon: '💡', label: '科技實踐' };
  if (['health', 'pe'].includes(subject)) return { icon: '🏃', label: '健體身心' };
  return { icon: '🧭', label: '綜合素養' };
}

export function renderKnowledgeFlowChart(u, pts, t) {
  const meta = getDomainMeta(u.subject);
  const firstPt = pts && pts[0] ? pts[0] : u.concept;
  const keyRow = t && t.rows && t.rows[0] ? t.rows[0] : [u.title, u.concept, u.example];
  const keyRule = keyRow[0] + '：' + keyRow[1];
  return `<div class="teaching-visual-chart" aria-label="${esc(u.title)} 視覺學習掌握圖解">
    <div class="teaching-chart-header">
      <div class="teaching-chart-meta">
        <span class="teaching-chart-domain-badge"><span aria-hidden="true">${meta.icon}</span> ${meta.label}</span>
        <span class="teaching-chart-step-badge">📈 108課綱思維掌握歷程</span>
      </div>
      <h4 class="teaching-chart-title">學習掌握思維圖解：從觀念啟發到遷移實戰</h4>
    </div>
    <div class="teaching-flow-grid" role="list">
      <div class="flow-card flow-card-core" role="listitem">
        <div class="flow-card-badge"><span aria-hidden="true">🎯</span> 概念起點</div>
        <div class="flow-card-body">
          <h5 class="flow-card-title">${esc(u.title)}</h5>
          <p class="flow-card-text">${esc(firstPt)}。</p>
        </div>
      </div>
      <div class="flow-connector" aria-hidden="true">
        <svg class="flow-arrow-svg" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M12 5l7 7-7 7"/></svg>
      </div>
      <div class="flow-card flow-card-rule" role="listitem">
        <div class="flow-card-badge"><span aria-hidden="true">⚖️</span> 判準法則</div>
        <div class="flow-card-body">
          <h5 class="flow-card-title">關鍵判斷規律</h5>
          <p class="flow-card-text">${esc(keyRule)}</p>
        </div>
      </div>
      <div class="flow-connector" aria-hidden="true">
        <svg class="flow-arrow-svg" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M12 5l7 7-7 7"/></svg>
      </div>
      <div class="flow-card flow-card-pitfall" role="listitem">
        <div class="flow-card-badge"><span aria-hidden="true">🛡️</span> 避坑防護</div>
        <div class="flow-card-body">
          <h5 class="flow-card-title">易錯界線檢查</h5>
          <p class="flow-card-text">${esc(u.pitfall)}</p>
        </div>
      </div>
      <div class="flow-connector" aria-hidden="true">
        <svg class="flow-arrow-svg" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M12 5l7 7-7 7"/></svg>
      </div>
      <div class="flow-card flow-card-task" role="listitem">
        <div class="flow-card-badge"><span aria-hidden="true">🚀</span> 遷移解題</div>
        <div class="flow-card-body">
          <h5 class="flow-card-title">實戰素養任務</h5>
          <p class="flow-card-text">${esc(u.task)}</p>
        </div>
      </div>
    </div>
  </div>`;
}

export function renderTeaching(u) {
 const t=teachingFor(u);
 const pts=knowledgePoints(u);
 const chartHtml = renderKnowledgeFlowChart(u, pts, t);
 return `<section class="teaching-notes" aria-label="逐點學習與比較表"><div class="teaching-notes-header"><div class="teaching-notes-title-wrap"><span class="teaching-badge">📊 108課綱核心知識點矩陣</span><h3>拆開理解，再連起來：${esc(u.title)}</h3></div><div class="knowledge-chips-row" role="list" aria-label="學習維度導覽"><span class="knowledge-chip" role="listitem">🎯 核心概念</span><span class="knowledge-chip" role="listitem">⚖️ 判準法則</span><span class="knowledge-chip" role="listitem">🔍 實證檢驗</span><span class="knowledge-chip" role="listitem">🛡️ 避坑防護</span></div></div>${chartHtml}<ol class="knowledge-list">${pts.map((p,i)=>`<li><span class="knowledge-point-tag">📌 知識要點 ${i+1}</span><strong>${esc(p)}。</strong></li>`).join('')}</ol><div class="table-wrap"><table class="teaching-table"><caption>${esc(t.title)}</caption><thead><tr><th scope="col">辨識重點</th><th scope="col">規則／條件</th><th scope="col">例子／檢查方法</th></tr></thead><tbody>${t.rows.map(row=>{const isCore=row[0].includes('核心判準');const isDefense=row[0].includes('易錯防線');const rowCls=isCore?' class="row-highlight-core"':(isDefense?' class="row-highlight-defense"':'');const icon=getRowIcon(row[0]);return `<tr${rowCls}>${row.map((v,i)=>i===0?`<th scope="row"><span class="row-icon" aria-hidden="true">${icon}</span> ${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`;}).join('')}</tbody></table></div><details class="worked-retrieval"><summary>先遮住講義：我能解釋「${esc(u.title)}」嗎？</summary><p>先口頭說出核心概念，再展開上表核對。最後完成這項遷移任務：</p><p>${esc(u.task)}</p><p class="subtle">能認出答案只是第一步；還要能說明理由、條件，以及何時不能套用。</p></details></section>`;
}
